insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('sunday-evening-week-preview-sheet', 'Sunday Evening Week Preview Sheet', 'worksheet'::resource_kind, 'A one-page look at the coming week that names the pinch points and one small kindness to schedule.', 'Use it to help a client walk into the week with a plan instead of a vague dread.', array['Adults']::text[], '20 minutes', 'Fill it in together on the day the client usually feels the week closing in. Start with the calendar, then move to the pinch points. The kindness box tends to be left blank at first, so ask what a small, real one would be. Check back at the next session on which pinch point went differently than expected.', '[{"id": "f0", "type": "textarea", "label": "The three days that look busiest"}, {"id": "f1", "type": "textarea", "label": "The pinch point on each of those days"}, {"id": "f2", "type": "textarea", "label": "What I can move, shrink or ask for help with"}, {"id": "f3", "type": "textarea", "label": "One small kindness I will schedule for myself"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this sheet this week"}]'::jsonb, array['planning', 'routines', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('daily-energy-bank-ledger', 'Daily Energy Bank Ledger', 'worksheet'::resource_kind, 'A ledger of what gives and takes energy across a day, with a plain balance at the end.', 'Use it to help a client see which parts of the day cost the most and plan around them.', array['Adults']::text[], 'One week', 'Ask the client to jot entries at three points in the day rather than all at night. Each item gets a plus or minus and a rough size. Look for the pattern across days, not the single bad one. Clients often find a small, cheap deposit they had been skipping, and that becomes the first change to try.', '[{"id": "f0", "type": "textarea", "label": "Morning: what gave energy and what took it"}, {"id": "f1", "type": "textarea", "label": "Midday: what gave energy and what took it"}, {"id": "f2", "type": "textarea", "label": "Evening: what gave energy and what took it"}, {"id": "f3", "type": "textarea", "label": "The biggest withdrawal this week"}, {"id": "f4", "type": "textarea", "label": "A small deposit I could add tomorrow"}, {"id": "f5", "type": "textarea", "label": "What I will do differently"}]'::jsonb, array['planning', 'self-monitoring', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('receiving-a-compliment-without-deflecting-page', 'Receiving a Compliment Without Deflecting Page', 'worksheet'::resource_kind, 'A page for noticing the quick brush-offs after kind words and trying a simple thank-you.', 'Use it to help a client let a kind word land and notice what happens inside when it does.', array['Adults', 'Teens']::text[], '15 minutes', 'Role-play a few compliments in session before assigning it. Many clients can say what they do (laugh it off, return one fast, change the subject) but not what they feel. Keep the replacement simple: thank you, and a breath. Look at the rating of discomfort across the week and see whether it drifts.', '[{"id": "f0", "type": "textarea", "label": "A compliment I received this week"}, {"id": "f1", "type": "textarea", "label": "What I said or did right after"}, {"id": "f2", "type": "textarea", "label": "What I felt in my body in that moment"}, {"id": "f3", "type": "textarea", "label": "A simple thank-you I could try next time"}, {"id": "f4", "type": "textarea", "label": "How uncomfortable it felt, 1 to 10, when I tried it"}]'::jsonb, array['self-compassion', 'communication', 'strengths']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('values-lens-decision-page', 'Values-Lens Decision Page', 'worksheet'::resource_kind, 'A page that runs a stuck decision past three of the client''s own values before any list of pros and cons.', 'Use it to help a client choose by what matters to them instead of by the loudest worry.', array['Adults']::text[], '25 minutes', 'Have the client name three values first, away from the decision, so they are not reverse-engineered. Then ask what each option would look like through each value. The page does not pick for them; it makes the tradeoff visible. Notice where a client tries to rank values to get the answer they already want.', '[{"id": "f0", "type": "textarea", "label": "The decision I am stuck on"}, {"id": "f1", "type": "textarea", "label": "Three values that matter to me"}, {"id": "f2", "type": "textarea", "label": "Option A, seen through each value"}, {"id": "f3", "type": "textarea", "label": "Option B, seen through each value"}, {"id": "f4", "type": "textarea", "label": "What I am afraid I will lose either way"}, {"id": "f5", "type": "textarea", "label": "The smallest step I can take this week"}]'::jsonb, array['values', 'planning', 'decision making']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('evening-landing-routine-designer', 'Evening Landing Routine Designer', 'worksheet'::resource_kind, 'A designer for a short, repeatable sequence that helps the day end instead of trailing on.', 'Use it to help a client build a routine they can actually keep at night.', array['Adults', 'Teens']::text[], '30 minutes', 'Keep it to three or four steps the client can do on their worst day. Ask what usually pulls the evening off course and build a step that meets it. Clients tend to over-design; cut the plan until it feels almost too small. Review in a week and adjust the order, not the willpower.', '[{"id": "f0", "type": "textarea", "label": "What usually happens between dinner and bed"}, {"id": "f1", "type": "textarea", "label": "What pulls me off course"}, {"id": "f2", "type": "textarea", "label": "Step one of my landing routine"}, {"id": "f3", "type": "textarea", "label": "Step two"}, {"id": "f4", "type": "textarea", "label": "Step three"}, {"id": "f5", "type": "textarea", "label": "The cue that tells me to begin"}, {"id": "f6", "type": "textarea", "label": "How I will know it worked"}]'::jsonb, array['routines', 'planning', 'sleep']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-out-interview-sheet', 'Mind-Reading Check-Out Interview Sheet', 'cbt'::resource_kind, 'A sheet for turning a guess about what someone thinks into a question the client could ask.', 'Use it to help a client test a mind-reading guess against what the other person says.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent moment where the client was sure what another person thought. Separate the guess from what was actually observed, then draft a low-stakes question to check it. Role-play asking it. Some clients will not ask; that is useful information, so explore what would make asking safer rather than pushing it.', '[{"id": "f0", "type": "textarea", "label": "What I was sure the other person thought"}, {"id": "f1", "type": "textarea", "label": "What I actually saw or heard"}, {"id": "f2", "type": "textarea", "label": "Other things they might have been thinking"}, {"id": "f3", "type": "textarea", "label": "A question I could ask to find out"}, {"id": "f4", "type": "textarea", "label": "How likely my first guess is now, 0 to 100"}]'::jsonb, array['thinking traps', 'core CBT', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('emotional-reasoning-reality-pause-sheet', 'Emotional Reasoning Reality Pause Sheet', 'cbt'::resource_kind, 'A sheet for the moments when "I feel it, so it must be true" takes over.', 'Use it to help a client separate a strong feeling from the facts of the situation.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce the idea that a feeling is real as a feeling and still not a report on the facts. Have the client fill it in right after a hard moment, then again a day later. The comparison is the teaching. Be careful not to sound as though the feeling is wrong; it is information, just not the whole picture.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The feeling and how strong it was, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What the feeling was telling me was true"}, {"id": "f3", "type": "textarea", "label": "What I can actually observe about the situation"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to say it"}, {"id": "f5", "type": "textarea", "label": "The feeling a day later"}]'::jsonb, array['thinking traps', 'core CBT', 'emotions']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('thought-to-behavior-chain-mapping-sheet', 'Thought-to-Behavior Chain Mapping Sheet', 'cbt'::resource_kind, 'A linked chain from trigger to thought to feeling to action to what happened next.', 'Use it to help a client see how one thought can steer a whole stretch of the day.', array['Adults', 'Teens']::text[], '30 minutes', 'Work through one recent episode live, drawing the links as arrows. Then ask where the chain could be loosened and what would happen if a different link were swapped in. Clients enjoy seeing it laid out. Keep the example small at first so it does not turn into a retelling of a painful event.', '[{"id": "f0", "type": "textarea", "label": "What set things off"}, {"id": "f1", "type": "textarea", "label": "The thought that came up"}, {"id": "f2", "type": "textarea", "label": "The feeling that followed"}, {"id": "f3", "type": "textarea", "label": "What I did next"}, {"id": "f4", "type": "textarea", "label": "What happened because of that"}, {"id": "f5", "type": "textarea", "label": "One link I could try changing"}]'::jsonb, array['core CBT', 'self-monitoring', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('prediction-versus-outcome-scorecard', 'Prediction Versus Outcome Scorecard', 'cbt'::resource_kind, 'A running scorecard comparing what the client predicted with what actually happened.', 'Use it to help a client check how accurate their predictions turn out to be over time.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask for three predictions a week, written before the event. The outcome column is filled in afterward, in plain language. The point is not to prove the client wrong but to let the evidence accumulate. Review the whole scorecard together after two weeks and ask what they notice about the gap.', '[{"id": "f0", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f1", "type": "textarea", "label": "How sure I was, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "How close my prediction was"}, {"id": "f4", "type": "textarea", "label": "What I notice across my scorecard so far"}]'::jsonb, array['behavioral experiment', 'core CBT', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('helpful-versus-unhelpful-thought-sort-cards', 'Helpful Versus Unhelpful Thought Sort Cards', 'cbt'::resource_kind, 'Cards for sorting thoughts by whether they help the client get where they want to go.', 'Use it to help a client judge a thought by its usefulness when its truth is hard to settle.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Write the client''s own recurring thoughts on cards and sort them into helpful, unhelpful and unsure. This works well when arguing about whether a thought is true goes nowhere. Ask what the unhelpful pile costs and what the helpful pile makes possible. Keep the sorting light and a little playful.', '[{"id": "f0", "type": "textarea", "label": "Five thoughts I notice often"}, {"id": "f1", "type": "textarea", "label": "Which ones went in the helpful pile"}, {"id": "f2", "type": "textarea", "label": "Which ones went in the unhelpful pile"}, {"id": "f3", "type": "textarea", "label": "What the unhelpful pile costs me"}, {"id": "f4", "type": "textarea", "label": "A thought I would like to practice more"}]'::jsonb, array['core CBT', 'thinking traps', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-metaphor-sheet', 'Passengers on the Bus Metaphor Sheet', 'act'::resource_kind, 'A sheet built around the bus metaphor, naming the passengers who are loud and where the client wants to drive.', 'Use it to help a client keep driving toward a value while difficult thoughts ride along.', array['Adults', 'Teens']::text[], '30 minutes', 'Tell the metaphor, then let the client name their loudest passengers and the direction they want to go. Ask what happens when they pull over to argue with a passenger. The sheet works best when the destination is a value, not a goal. Revisit it whenever the client feels stuck in a shouting match with their own mind.', '[{"id": "f0", "type": "textarea", "label": "The direction I want to drive in"}, {"id": "f1", "type": "textarea", "label": "The loudest passengers on my bus"}, {"id": "f2", "type": "textarea", "label": "What they say when I turn that way"}, {"id": "f3", "type": "textarea", "label": "What happens when I stop to argue with them"}, {"id": "f4", "type": "textarea", "label": "One turn I can make this week with them aboard"}]'::jsonb, array['core ACT', 'values', 'defusion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('hooks-and-unhooking-tracking-sheet', 'Hooks and Unhooking Tracking Sheet', 'act'::resource_kind, 'A tracker for noticing what hooks the client and what they do to get unhooked.', 'Use it to help a client spot the moment of being hooked and try a different move.', array['Adults', 'Teens']::text[], 'One week', 'Describe getting hooked as being pulled along by a thought or feeling and doing what it says without choosing to. The client logs the hook, the pull and the move they made. Include moves that move them toward a value and moves that move them away; neither is a failure, just information. Review for patterns in the hooks.', '[{"id": "f0", "type": "textarea", "label": "What hooked me"}, {"id": "f1", "type": "textarea", "label": "How it pulled at me"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "Whether that moved me toward or away from what matters"}, {"id": "f4", "type": "textarea", "label": "What I could try instead next time"}]'::jsonb, array['core ACT', 'defusion', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('willing-hands-open-palm-practice', 'Willing Hands Open-Palm Practice', 'act'::resource_kind, 'A short practice using an open palm to rehearse making room for an uncomfortable feeling.', 'Use it to help a client physically rehearse the stance of willingness.', array['Adults', 'Teens']::text[], '10 minutes', 'Lead it in session first so the client knows how it feels. Contrast a clenched fist, which is pushing away, with an open palm, which is making room. Invite them to notice what changes in their shoulders and breath. Not everyone enjoys body-based practice; offer a seated or eyes-open version.', '[{"id": "f0", "type": "textarea", "label": "A feeling I tend to clench against"}, {"id": "f1", "type": "textarea", "label": "What the clenched version feels like"}, {"id": "f2", "type": "textarea", "label": "What the open-palm version feels like"}, {"id": "f3", "type": "textarea", "label": "Where I could use the open palm this week"}, {"id": "f4", "type": "textarea", "label": "What I will do while I make room for it"}]'::jsonb, array['core ACT', 'willingness', 'acceptance']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('valued-living-compass-check-in', 'Valued Living Compass Check-In', 'act'::resource_kind, 'A check-in across a few life areas comparing how important each is with how much the client has lived it lately.', 'Use it to help a client find the area where a small valued step would matter most.', array['Adults']::text[], '25 minutes', 'Choose four or five areas with the client rather than using a fixed list. Rate importance and recent action separately. The gap is where the conversation lives, but do not treat it as a score to fix everywhere at once. Pick one area and one step that is small enough to happen this week.', '[{"id": "f0", "type": "textarea", "label": "The life areas I want to look at"}, {"id": "f1", "type": "textarea", "label": "How much each matters to me, 1 to 10"}, {"id": "f2", "type": "textarea", "label": "How much I have lived it lately, 1 to 10"}, {"id": "f3", "type": "textarea", "label": "The area with the biggest gap"}, {"id": "f4", "type": "textarea", "label": "One small step I will take there"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-thought-parade-log', 'Leaves on a Stream Thought Parade Log', 'act'::resource_kind, 'A log used after the leaves-on-a-stream exercise to record what drifted by and how it felt to watch.', 'Use it to help a client practice watching thoughts without hooking into them.', array['Adults', 'Teens']::text[], '15 minutes', 'Guide the exercise live, then use the log. Many clients get frustrated when thoughts do not stay put on a leaf; normalize that and invite them to simply come back. The log tracks what showed up, not whether they did it right. Offer short versions to use at home.', '[{"id": "f0", "type": "textarea", "label": "A few thoughts that floated by"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I labeled them as thoughts"}, {"id": "f2", "type": "textarea", "label": "When I got pulled into a thought"}, {"id": "f3", "type": "textarea", "label": "How I came back to watching"}, {"id": "f4", "type": "textarea", "label": "Where I could use this during the week"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('tipp-body-reset-rehearsal-card', 'TIPP Body Reset Rehearsal Card', 'dbt'::resource_kind, 'A card for rehearsing the temperature, intense exercise, paced breathing and paired relaxation skills before they are needed.', 'Use it to help a client practice the TIPP steps while calm so they are ready when upset.', array['Adults', 'Teens']::text[], '20 minutes', 'Rehearse each step in session, choosing the ones that are realistic for the client''s body and setting. Cold water is not right for everyone, so talk through any health concerns first. Have the client rank the four by how doable they are. A practiced card in a pocket beats a perfect plan they have never tried.', '[{"id": "f0", "type": "textarea", "label": "The step I find easiest to do"}, {"id": "f1", "type": "textarea", "label": "The step I find hardest"}, {"id": "f2", "type": "textarea", "label": "Where I could do each one in my day"}, {"id": "f3", "type": "textarea", "label": "What I notice in my body after paced breathing"}, {"id": "f4", "type": "textarea", "label": "When I will rehearse this again"}]'::jsonb, array['core DBT', 'distress tolerance', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-turning-the-mind-log', 'Radical Acceptance Turning-the-Mind Log', 'dbt'::resource_kind, 'A log for the many times a client has to turn the mind back to acceptance on one painful fact.', 'Use it to help a client see acceptance as something they return to again and again.', array['Adults', 'Teens']::text[], 'One week', 'Explain that accepting a hard reality is rarely a single decision; the mind drifts back to fighting it. The client marks each time they notice and turn back. Include the fact being accepted, written plainly. Be clear that acceptance is not approval. Review the log for what made turning easier.', '[{"id": "f0", "type": "textarea", "label": "The reality I am working on accepting"}, {"id": "f1", "type": "textarea", "label": "Times I noticed myself fighting it"}, {"id": "f2", "type": "textarea", "label": "What I said or did to turn my mind back"}, {"id": "f3", "type": "textarea", "label": "What made turning easier"}, {"id": "f4", "type": "textarea", "label": "What I can do next with this reality as it is"}]'::jsonb, array['core DBT', 'acceptance', 'distress tolerance']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('opposite-action-experiment-planner', 'Opposite Action Experiment Planner', 'dbt'::resource_kind, 'A planner for choosing one emotion-driven urge and trying the opposite action in a small, safe way.', 'Use it to help a client test what happens when they act opposite to an urge that is not serving them.', array['Adults', 'Teens']::text[], '25 minutes', 'Start by checking whether the emotion fits the facts; opposite action is for when it does not, or when acting on it will not help. Pick a low-stakes situation first. The client predicts what will happen, tries it, and records the result. Practice the full opposite action, including posture and tone.', '[{"id": "f0", "type": "textarea", "label": "The emotion and the urge it brings"}, {"id": "f1", "type": "textarea", "label": "Whether the emotion fits the facts"}, {"id": "f2", "type": "textarea", "label": "The opposite action I will try"}, {"id": "f3", "type": "textarea", "label": "What I predict will happen"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I learned about the urge"}]'::jsonb, array['core DBT', 'emotion regulation', 'behavioral experiment']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-skills-use-versus-old-habit-sheet', 'Pros and Cons of Skills Use Versus Old Habit Sheet', 'dbt'::resource_kind, 'A two-by-two sheet comparing using a skill with falling back on an old habit, in the short and the long run.', 'Use it to help a client weigh a hard moment honestly and choose with their eyes open.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill in the old habit side first so the client feels heard about what it gives them. Then fill in the skill side. Resist arguing; the sheet does the persuading. Keep a copy handy for the next time the old habit pulls. Clients often discover that the short-term pro of the old habit is real and still not worth the long-term con.', '[{"id": "f0", "type": "textarea", "label": "The old habit and the moment it shows up"}, {"id": "f1", "type": "textarea", "label": "What it gives me now"}, {"id": "f2", "type": "textarea", "label": "What it costs me later"}, {"id": "f3", "type": "textarea", "label": "The skill I could use instead"}, {"id": "f4", "type": "textarea", "label": "What it gives me and costs me"}, {"id": "f5", "type": "textarea", "label": "My choice this time"}]'::jsonb, array['core DBT', 'distress tolerance', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('wise-mind-walking-reflection-page', 'Wise Mind Walking Reflection Page', 'dbt'::resource_kind, 'A page used after a mindful walk to notice where emotion and reason meet.', 'Use it to help a client find wise mind through attention to the body and surroundings.', array['Adults', 'Teens']::text[], '20 minutes', 'Take a short walk with the client or assign one, asking them to pay attention to feet, breath and what they see. Afterward they note what felt calm and what felt busy. Wise mind is hard to describe, so use their own words. A question to carry: what does my wise mind say about the thing I am facing?', '[{"id": "f0", "type": "textarea", "label": "Where I walked"}, {"id": "f1", "type": "textarea", "label": "What my feet and breath felt like"}, {"id": "f2", "type": "textarea", "label": "What my emotional mind said"}, {"id": "f3", "type": "textarea", "label": "What my reasonable mind said"}, {"id": "f4", "type": "textarea", "label": "What wise mind says about my situation"}]'::jsonb, array['core DBT', 'mindfulness', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('repair-attempt-preference-menu-for-partners', 'Repair Attempt Preference Menu for Partners', 'couples'::resource_kind, 'Each partner lists the repair moves that work for them and shares them as a menu.', 'Use it to help a couple recognize and accept each other''s attempts to repair mid-conflict.', array['Couples']::text[], '30 minutes', 'Each partner works alone first, then they swap. Partner A lists repairs that would help them and Partner B does the same. Ask each to name one repair the other already does that they have missed. Model receiving a repair attempt in session. Many couples find they were offering repairs in a language the other did not hear.', '[{"id": "f0", "type": "textarea", "label": "Partner A: repairs that help me when we are tense"}, {"id": "f1", "type": "textarea", "label": "Partner B: repairs that help me when we are tense"}, {"id": "f2", "type": "textarea", "label": "A repair my partner already offers that I missed"}, {"id": "f3", "type": "textarea", "label": "A repair I would like to try offering"}, {"id": "f4", "type": "textarea", "label": "How we will signal we are making a repair attempt"}]'::jsonb, array['couples', 'conflict', 'Gottman']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('weekly-appreciation-handoff-cards', 'Weekly Appreciation Handoff Cards', 'couples'::resource_kind, 'Partners write one specific appreciation a day and hand the card over.', 'Use it to help a couple build a daily habit of noticing what is going right between them.', array['Couples']::text[], 'One week', 'Each partner writes one card a day about something specific the other did. Keep them short and about actions, not traits. Do not make it a scoreboard. In session, ask each how it felt to write and how it felt to receive. If one partner struggles to find anything, explore that gently rather than pressing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciated today"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciated today"}, {"id": "f2", "type": "textarea", "label": "How it felt to receive a card"}, {"id": "f3", "type": "textarea", "label": "Something I want more of"}, {"id": "f4", "type": "textarea", "label": "What we will keep doing next week"}]'::jsonb, array['couples', 'connection', 'Gottman']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('stress-tag-team-agreement', 'Stress Tag Team Agreement', 'couples'::resource_kind, 'A short agreement for how each partner wants help on a heavy day and what to avoid saying.', 'Use it to help a couple name what support looks like before the next stressful day arrives.', array['Couples']::text[], '30 minutes', 'Each partner answers separately about what helps and what does not on a heavy day, then they compare. Look for mismatches such as one wanting solutions and the other wanting company. Write the agreement in plain words they can both live with. Review it after a real stressful day to see what held.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me on a heavy day"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me on a heavy day"}, {"id": "f2", "type": "textarea", "label": "What each of us wants to avoid hearing"}, {"id": "f3", "type": "textarea", "label": "How we will ask for what we need"}, {"id": "f4", "type": "textarea", "label": "When we will check this agreement again"}]'::jsonb, array['couples', 'support', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('unspoken-rules-we-inherited-interview', 'Unspoken Rules We Inherited Interview', 'couples'::resource_kind, 'Partners compare the unspoken rules each grew up with about money, anger, affection and chores.', 'Use it to help a couple see that some clashes come from different family habits, not from one partner being wrong.', array['Couples']::text[], 'Full session', 'Ask each partner to answer for their own family first, then listen without correcting. Common themes are who handles money, how anger is shown and who cleans up. Invite curiosity rather than blame. End by choosing one rule they want to keep, one to retire and one to rewrite together.', '[{"id": "f0", "type": "textarea", "label": "A rule in my family about money or chores"}, {"id": "f1", "type": "textarea", "label": "A rule about how anger or upset was shown"}, {"id": "f2", "type": "textarea", "label": "A rule about affection"}, {"id": "f3", "type": "textarea", "label": "A rule we want to keep"}, {"id": "f4", "type": "textarea", "label": "A rule we want to retire or rewrite"}]'::jsonb, array['couples', 'family', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('two-lane-conversation-practice-sheet', 'Two-Lane Conversation Practice Sheet', 'couples'::resource_kind, 'A structure with a speaker lane and a listener lane for a conversation about one topic.', 'Use it to help partners stay in their lane long enough to feel heard.', array['Couples']::text[], '30 minutes', 'One partner speaks for a short fixed time while the other only listens and then reflects back what they heard, without defending. Swap. Choose a mild topic first, not the biggest fight. Coach the listener to reflect, not rebut. Check afterward what it felt like to be in each lane.', '[{"id": "f0", "type": "textarea", "label": "The topic we chose"}, {"id": "f1", "type": "textarea", "label": "Speaker: what I want my partner to understand"}, {"id": "f2", "type": "textarea", "label": "Listener: what I heard"}, {"id": "f3", "type": "textarea", "label": "What the speaker would add or correct"}, {"id": "f4", "type": "textarea", "label": "What it felt like to listen without defending"}]'::jsonb, array['couples', 'communication', 'conflict']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('my-feelings-weather-window-craft', 'My Feelings Weather Window Craft', 'kids'::resource_kind, 'A paper window frame where a child draws the weather that matches the feeling inside.', 'Use it to help a child show a feeling through a picture when words are hard to find.', array['Children']::text[], '20 minutes', 'Let the child decorate the frame and draw today''s weather through it. Ask what kind of day it is inside. Parents can later use the window as a quick check-in at home by asking what weather it is. Follow the child''s lead on the drawing and avoid interpreting it for them.', '[{"id": "f0", "type": "textarea", "label": "The weather I drew today"}, {"id": "f1", "type": "textarea", "label": "What feeling that weather matches"}, {"id": "f2", "type": "textarea", "label": "What would make the weather change"}, {"id": "f3", "type": "textarea", "label": "Who I can show my window to"}]'::jsonb, array['kids', 'emotions', 'art']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-with-sparkles-build', 'Calm Down Jar With Sparkles Build', 'kids'::resource_kind, 'The child builds a sparkle jar and uses it to watch their upset settle.', 'Use it to help a child watch a big feeling settle like glitter in water.', array['Children']::text[], '25 minutes', 'Build the jar together with water, glue and glitter, sealed well. Show how shaking it looks like a big feeling and how watching it settle is something the child can do. Parent role: keep the jar somewhere the child can reach and sit with them rather than send them away with it. It is a tool for company, not a punishment.', '[{"id": "f0", "type": "textarea", "label": "What my sparkles look like when I am upset"}, {"id": "f1", "type": "textarea", "label": "How long it takes them to settle"}, {"id": "f2", "type": "textarea", "label": "What I feel in my body while I watch"}, {"id": "f3", "type": "textarea", "label": "Where our jar lives at home"}]'::jsonb, array['kids', 'regulation', 'play']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('bravery-badge-maker', 'Bravery Badge Maker', 'kids'::resource_kind, 'A child designs badges for brave things they did and earns new ones across the week.', 'Use it to help a child notice and name the brave things they do, big or small.', array['Children']::text[], '25 minutes', 'Have the child decorate blank paper badges and name the brave act on each. Ask a parent to notice and name small acts at home, like trying something new. Keep the badges about effort and not outcome. Check in on which ones the child is most proud of and what kind of bravery they want to try next.', '[{"id": "f0", "type": "textarea", "label": "A brave thing I did this week"}, {"id": "f1", "type": "textarea", "label": "What my badge looks like"}, {"id": "f2", "type": "textarea", "label": "What helped me be brave"}, {"id": "f3", "type": "textarea", "label": "A brave thing I want to try next"}, {"id": "f4", "type": "textarea", "label": "Who I will tell about it"}]'::jsonb, array['kids', 'strengths', 'children']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('feelings-zoo-animal-matching-play', 'Feelings Zoo Animal Matching Play', 'kids'::resource_kind, 'The child matches animals to feelings and acts them out.', 'Use it to help a child connect feelings with bodies and faces through play.', array['Children']::text[], '20 minutes', 'Lay out animal cards and let the child pick one for each feeling, then act it out. A parent joins, matches too and says what their animal feels. Take turns guessing. Do not correct the child''s choices; a sleepy lion for worry is theirs. The goal is a shared vocabulary for use at home.', '[{"id": "f0", "type": "textarea", "label": "The animal for my happiest feeling"}, {"id": "f1", "type": "textarea", "label": "The animal for my angry feeling"}, {"id": "f2", "type": "textarea", "label": "The animal for my worried feeling"}, {"id": "f3", "type": "textarea", "label": "Which animal is like me today"}, {"id": "f4", "type": "textarea", "label": "How my parent and I can use our animals at home"}]'::jsonb, array['kids', 'emotions', 'play']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('goodnight-worry-mailbox-craft', 'Goodnight Worry Mailbox Craft', 'kids'::resource_kind, 'A decorated box where a child posts worries before bed for a parent to read together.', 'Use it to help a child hand off bedtime worries so they do not have to carry them alone.', array['Children']::text[], '30 minutes', 'Build the mailbox from a small box and slot. The child draws or dictates a worry, posts it, and the parent promises a short time in the morning to read it together. Parent role: stay calm, listen, and avoid long reassurance at bedtime. Reporting duties apply if a child discloses anything about being unsafe.', '[{"id": "f0", "type": "textarea", "label": "What my mailbox looks like"}, {"id": "f1", "type": "textarea", "label": "A worry I posted tonight"}, {"id": "f2", "type": "textarea", "label": "Who reads the mail with me"}, {"id": "f3", "type": "textarea", "label": "What we do with the worry in the morning"}]'::jsonb, array['kids', 'sleep', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('skill-of-the-day-spinner-game', 'Skill of the Day Spinner Game', 'game'::resource_kind, 'Players spin for a coping skill, then act out or describe when they would use it.', 'Use it to help a group rehearse skills in a quick, low-pressure round.', array['Teens', 'Groups', 'Adults']::text[], '25 minutes', 'Make a spinner with a skill on each wedge. Rules: spin, describe a time you would use the skill, and the group adds one tip. Turns rotate around the circle and anyone can pass. Debrief by asking which skills people want to take home and which were new. Keep the energy light so the learning sticks.', '[{"id": "f0", "type": "textarea", "label": "The skill I landed on"}, {"id": "f1", "type": "textarea", "label": "A moment I would use it"}, {"id": "f2", "type": "textarea", "label": "A tip from the group I liked"}, {"id": "f3", "type": "textarea", "label": "The skill I will try this week"}]'::jsonb, array['game', 'group', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('two-facts-and-a-strength-guessing-game', 'Two Facts and a Strength Guessing Game', 'game'::resource_kind, 'Players share two true things and one strength, and the group guesses which is the strength.', 'Use it to help a group practice naming strengths out loud without awkwardness.', array['Teens', 'Groups', 'Adults']::text[], '20 minutes', 'Rules: each player states three things, two ordinary facts and one real strength, and others guess the strength. Turns go clockwise. For debrief, ask what it was like to say a strength and what was easier, the facts or the strength. Support players who feel stuck by letting the group offer ideas.', '[{"id": "f0", "type": "textarea", "label": "Two true things about me"}, {"id": "f1", "type": "textarea", "label": "A strength I named"}, {"id": "f2", "type": "textarea", "label": "What it felt like to say it"}, {"id": "f3", "type": "textarea", "label": "A strength I heard in someone else"}]'::jsonb, array['game', 'strengths', 'group']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('emotion-charades-pass-the-card', 'Emotion Charades Pass the Card', 'game'::resource_kind, 'Players act out a feeling card in silence while the group guesses and shares a time they felt it.', 'Use it to help a group recognize feelings in bodies and talk about when they show up.', array['Teens', 'Groups', 'Children']::text[], '25 minutes', 'Rules: draw a card, act out the feeling without words, group guesses. The guesser then shares a brief time they felt it, or passes. Turns rotate. Debrief on how feelings looked different on different people. For children, a parent or helper can act too. Keep it playful and let anyone sit out a round.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out"}, {"id": "f1", "type": "textarea", "label": "How the group knew"}, {"id": "f2", "type": "textarea", "label": "A time I felt something like that"}, {"id": "f3", "type": "textarea", "label": "A feeling that was hard to act out"}]'::jsonb, array['game', 'emotions', 'play']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('problem-solving-relay-game', 'Problem-Solving Relay Game', 'game'::resource_kind, 'Teams pass a problem card down the line, each adding one possible solution.', 'Use it to help a group brainstorm many solutions before choosing one.', array['Teens', 'Groups', 'Adults']::text[], '30 minutes', 'Rules: each team gets a problem card and a timer. Players take turns adding one solution each, no judging, and the last player circles the one the team would try. Debrief by asking how it felt to hear so many options and what changed when nobody shot ideas down. Link it to a real problem someone is facing.', '[{"id": "f0", "type": "textarea", "label": "The problem on our card"}, {"id": "f1", "type": "textarea", "label": "Solutions our team came up with"}, {"id": "f2", "type": "textarea", "label": "The one we would try and why"}, {"id": "f3", "type": "textarea", "label": "A real problem I could use this on"}]'::jsonb, array['game', 'skills', 'group']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('mindful-moment-bingo-challenge', 'Mindful Moment Bingo Challenge', 'game'::resource_kind, 'Players mark squares for small mindful moments across the week and bring the card back.', 'Use it to help a client notice the present moment in everyday life through a simple challenge.', array['Adults', 'Teens', 'Groups']::text[], 'One week', 'Make a card with squares like noticing the taste of the first bite or the feel of warm water. Rules: mark a square when you do it, and bring the card back. Turns are not needed; it is a solo challenge shared in session. Debrief on the easiest and hardest squares and what the client noticed.', '[{"id": "f0", "type": "textarea", "label": "The squares I marked"}, {"id": "f1", "type": "textarea", "label": "The easiest moment to notice"}, {"id": "f2", "type": "textarea", "label": "The hardest one"}, {"id": "f3", "type": "textarea", "label": "Something I noticed that surprised me"}]'::jsonb, array['game', 'mindfulness', 'play']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('present-day-anchors-inventory', 'Present-Day Anchors Inventory', 'worksheet'::resource_kind, 'An inventory of people, places and objects that tell the client''s body it is here and now.', 'Use it to help a client gather present-day anchors they can reach for when reminders arise.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep this entirely in the present: what is in the room, who is reliable, what is safe today. Do not ask for details about past events. Have the client carry a short list on a phone or card. Revisit it as anchors change, and add new ones when the old ones stop working.', '[{"id": "f0", "type": "textarea", "label": "People who help me feel steady"}, {"id": "f1", "type": "textarea", "label": "Places where my body relaxes a little"}, {"id": "f2", "type": "textarea", "label": "Objects I can hold or look at"}, {"id": "f3", "type": "textarea", "label": "Sounds or smells that remind me I am here now"}, {"id": "f4", "type": "textarea", "label": "The anchor I will keep with me this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('reminder-versus-danger-sorting-sheet', 'Reminder Versus Danger Sorting Sheet', 'cbt'::resource_kind, 'A sheet for sorting what is a reminder of the past from what is a present-day risk.', 'Use it to help a client pause and check what is happening now when a reminder hits.', array['Adults', 'Teens']::text[], '25 minutes', 'Work only with present-day situations the client names, not with the memory itself. The sheet asks what is here now, what is a reminder, and what actually puts them at risk today. Move slowly and let the client set the pace. If the sheet stirs up too much, stop and ground first.', '[{"id": "f0", "type": "textarea", "label": "A moment when my body reacted strongly"}, {"id": "f1", "type": "textarea", "label": "What was actually happening around me"}, {"id": "f2", "type": "textarea", "label": "What it reminded me of, in a few words only"}, {"id": "f3", "type": "textarea", "label": "What is different about today"}, {"id": "f4", "type": "textarea", "label": "What I can do to help my body settle"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'grounding']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('making-room-while-staying-grounded-pacing-sheet', 'Making Room While Staying Grounded Pacing Sheet', 'act'::resource_kind, 'A pacing sheet that pairs willingness with grounding so a client approaches hard feelings in small amounts.', 'Use it to help a client make room for feelings in measured steps while staying anchored.', array['Adults']::text[], '25 minutes', 'Pacing is the point: small amounts, then back to the anchors. Teach the client that they decide when to pause. Avoid inviting detail about what happened. Check how the practice felt in the body and adjust the length down if it was too much. Some clients prefer to start with only noticing a sensation.', '[{"id": "f0", "type": "textarea", "label": "A feeling I could make a little room for today"}, {"id": "f1", "type": "textarea", "label": "How long I will stay with it before I ground"}, {"id": "f2", "type": "textarea", "label": "My grounding anchor for coming back"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f4", "type": "textarea", "label": "How I decided to pause or continue"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'pacing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('window-pacing-dial-for-hard-days', 'Window Pacing Dial for Hard Days', 'dbt'::resource_kind, 'A dial from calm to overloaded with a skill matched to each setting.', 'Use it to help a client notice where they are on the dial and match a skill to it.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw the dial together and agree on what each zone feels like for this client. At the high end, grounding and paced breathing come first; at the low end, gentle movement or contact. This is a personal tool, not a measurement. Review which skills fit which zone and update the dial after hard weeks.', '[{"id": "f0", "type": "textarea", "label": "What a calm day feels like in my body"}, {"id": "f1", "type": "textarea", "label": "What starting to overload feels like"}, {"id": "f2", "type": "textarea", "label": "A skill for when I am starting to overload"}, {"id": "f3", "type": "textarea", "label": "A skill for when I feel shut down"}, {"id": "f4", "type": "textarea", "label": "Who I can contact if the dial goes too high"}]'::jsonb, array['PTSD and trauma', 'core DBT', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('here-and-now-orientation-card-game', 'Here and Now Orientation Card Game', 'game'::resource_kind, 'A card game where players name what they can see, hear and touch in the room right now.', 'Use it to help a group practice noticing the present moment in a light, predictable way.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Rules: each card asks for one thing in the room, like something blue or something soft. Players take turns drawing and answering, and anyone can pass. Keep it playful and predictable. Debrief on how it felt to look around and which cards were easiest. It is practice in orienting, not a discussion of the past.', '[{"id": "f0", "type": "textarea", "label": "The card I drew"}, {"id": "f1", "type": "textarea", "label": "What I noticed in the room"}, {"id": "f2", "type": "textarea", "label": "What my body felt like afterward"}, {"id": "f3", "type": "textarea", "label": "A way I can do this on my own"}]'::jsonb, array['PTSD and trauma', 'game', 'grounding']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('worry-postponement-window-calendar', 'Worry Postponement Window Calendar', 'worksheet'::resource_kind, 'A weekly calendar that places a short worry window and tracks what is left over at the end.', 'Use it to help a client set worries aside until a set time and see how many are still there.', array['Adults', 'Teens']::text[], 'One week', 'Choose a window that is not near bedtime. The client jots worries as they come and revisits the list in the window. Many find that fewer need attention by then. Expect it to feel unnatural at first; keep the window short and consistent. Ask what was left on the list and what they did with it.', '[{"id": "f0", "type": "textarea", "label": "When my worry window is each day"}, {"id": "f1", "type": "textarea", "label": "Worries I wrote down to save for later"}, {"id": "f2", "type": "textarea", "label": "Which ones still mattered when the window came"}, {"id": "f3", "type": "textarea", "label": "What I did about the ones that mattered"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my day outside the window"}]'::jsonb, array['anxiety', 'planning', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-experiment-log', 'Uncertainty Tolerance Experiment Log', 'cbt'::resource_kind, 'A log for deliberately leaving small things uncertain and recording what happens.', 'Use it to help a client test how it feels to not know and not fix.', array['Adults', 'Teens']::text[], 'Two weeks', 'Pick small, safe uncertainties, such as not rechecking a message. The client predicts the distress, tries it, and records the actual result. Increase gradually. Be clear that the aim is not to prove anything bad cannot happen but to build comfort with not knowing. Review the pattern in what they predicted versus what they felt.', '[{"id": "f0", "type": "textarea", "label": "The small uncertainty I chose"}, {"id": "f1", "type": "textarea", "label": "How much distress I predict, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I did instead of fixing it"}, {"id": "f3", "type": "textarea", "label": "How much distress I felt"}, {"id": "f4", "type": "textarea", "label": "What I learned about not knowing"}]'::jsonb, array['anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-chatty-neighbor-defusion-sheet', 'Anxious Mind as a Chatty Neighbor Defusion Sheet', 'act'::resource_kind, 'A sheet that casts the anxious mind as a chatty neighbor whose talk can be noted without obeying.', 'Use it to help a client notice worry as talk rather than instructions.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to name their mind''s recurring lines as if a neighbor said them over the fence. Humor often helps. The client chooses what to do while the neighbor keeps talking. Be careful not to dismiss worry as silly; the point is choice, not suppression. Practice during the week and bring back the best lines.', '[{"id": "f0", "type": "textarea", "label": "What my neighbor said this week"}, {"id": "f1", "type": "textarea", "label": "What it wanted me to do"}, {"id": "f2", "type": "textarea", "label": "What I chose to do instead"}, {"id": "f3", "type": "textarea", "label": "What mattered more to me than listening"}]'::jsonb, array['anxiety', 'core ACT', 'defusion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anxiety-body-check-and-soothe-plan', 'Anxiety Body Check and Soothe Plan', 'dbt'::resource_kind, 'A body scan paired with a menu of soothing skills for each sensation.', 'Use it to help a client link body sensations with a skill that eases them.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the body from head to feet, naming where anxiety shows up. For each spot, choose a skill, such as paced breathing for the chest or a warm drink for the hands. The plan should be small enough to use at a desk. Review which pairings the client actually used.', '[{"id": "f0", "type": "textarea", "label": "Where anxiety shows up in my body"}, {"id": "f1", "type": "textarea", "label": "A skill that fits each place"}, {"id": "f2", "type": "textarea", "label": "Which skill I will try first"}, {"id": "f3", "type": "textarea", "label": "What happened when I used it"}, {"id": "f4", "type": "textarea", "label": "What I will add to my plan"}]'::jsonb, array['anxiety', 'core DBT', 'self-soothing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('worry-monster-name-and-tame-drawing', 'Worry Monster Name and Tame Drawing', 'kids'::resource_kind, 'A child draws their worry as a monster, gives it a silly name and decides what it needs.', 'Use it to help a child make a worry less scary by drawing and naming it.', array['Children']::text[], '25 minutes', 'Let the child draw their worry as a creature and give it a name and a silly voice. Ask what it is afraid of and what it needs to calm down. A parent watches and learns the language the child uses, then uses it at home. Do not rush to talk the child out of the worry; simply make room for it.', '[{"id": "f0", "type": "textarea", "label": "What my worry monster looks like"}, {"id": "f1", "type": "textarea", "label": "Its silly name"}, {"id": "f2", "type": "textarea", "label": "What it is afraid of"}, {"id": "f3", "type": "textarea", "label": "What it needs to calm down"}, {"id": "f4", "type": "textarea", "label": "What a parent can say when it shows up"}]'::jsonb, array['anxiety', 'kids', 'art']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('low-mood-day-menu-of-minimums', 'Low-Mood Day Menu of Minimums', 'worksheet'::resource_kind, 'A menu of the smallest versions of daily tasks for days when everything feels heavy.', 'Use it to help a client keep a floor under their day when energy is very low.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the menu on a better day so it is ready on a hard one. Each item is the minimum: a glass of water, one text, five minutes outside. Avoid making it a to-do list that becomes another source of guilt. Review which minimums were used and which felt too big, and shrink those.', '[{"id": "f0", "type": "textarea", "label": "The smallest way I can take care of my body"}, {"id": "f1", "type": "textarea", "label": "The smallest way I can connect with someone"}, {"id": "f2", "type": "textarea", "label": "The smallest thing I can do outside"}, {"id": "f3", "type": "textarea", "label": "A minimum for something I usually care about"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this menu"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('mood-and-activity-pairing-chart', 'Mood and Activity Pairing Chart', 'cbt'::resource_kind, 'A chart that pairs daily activities with mood ratings to find what lifts and what drains.', 'Use it to help a client find which activities are worth doing more or less.', array['Adults', 'Teens']::text[], 'One week', 'Ask for entries at set times of day with two ratings, pleasure and sense of accomplishment. At review, look for the surprises, such as a short walk that scores higher than expected. Pick one activity to schedule more of. Keep the tone curious; the chart is not a verdict on the client''s week.', '[{"id": "f0", "type": "textarea", "label": "What I did in this time block"}, {"id": "f1", "type": "textarea", "label": "Pleasure, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Sense of accomplishment, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What stood out when I looked across the week"}, {"id": "f4", "type": "textarea", "label": "One activity I will schedule more of"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('small-valued-steps-for-heavy-days-planner', 'Small Valued Steps for Heavy Days Planner', 'act'::resource_kind, 'A planner that connects a value to the smallest step that can be taken even when mood is low.', 'Use it to help a client act on a value without waiting to feel better first.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose one value and the tiniest action that fits it, such as texting a friend as an act of connection. Explain that action can come before the feeling. Check the plan against the client''s actual energy and shrink it if it looks heavy. Celebrate the doing, not the mood afterward.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "The smallest step that fits it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it"}, {"id": "f3", "type": "textarea", "label": "What my mind may say about it"}, {"id": "f4", "type": "textarea", "label": "How I will do it anyway"}]'::jsonb, array['depression', 'core ACT', 'committed action']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('reasons-to-stay-and-support-card', 'Reasons to Stay and Support Card', 'dbt'::resource_kind, 'A pocket card with the client''s reasons, supports and a place for 988.', 'Use it to help a client keep their reasons and their supports within reach.', array['Adults', 'Teens']::text[], 'Full session', 'Complete it with the client in session, not as homework. Use their words for the reasons. Include people to contact and the 988 Suicide and Crisis Lifeline (call or text 988) if thoughts of ending their life come up. Check whether the card feels usable and update it together, and follow your own risk procedures.', '[{"id": "f0", "type": "textarea", "label": "Reasons that matter to me"}, {"id": "f1", "type": "textarea", "label": "People I can contact and how"}, {"id": "f2", "type": "textarea", "label": "Things I can do to get through a hard hour"}, {"id": "f3", "type": "textarea", "label": "The 988 Suicide and Crisis Lifeline: call or text 988"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['depression', 'core DBT', 'support', 'safety']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('partner-support-plan-for-low-mood-weeks', 'Partner Support Plan for Low Mood Weeks', 'couples'::resource_kind, 'A plan for how a partner can help in low-mood weeks without taking over.', 'Use it to help a couple agree on supportive actions and boundaries during heavy stretches.', array['Couples']::text[], '30 minutes', 'Each partner says what helps and what they can offer. Keep requests concrete, like cooking together or a short walk. The supporting partner also names what they need so they do not burn out. Treat the plan as a draft and review it after a hard week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when my mood is low"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f2", "type": "textarea", "label": "What I need so I do not burn out"}, {"id": "f3", "type": "textarea", "label": "A signal we will use when it is a heavy day"}, {"id": "f4", "type": "textarea", "label": "When we will review this plan"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('doorway-launch-pad-setup-sheet', 'Doorway Launch Pad Setup Sheet', 'worksheet'::resource_kind, 'A sheet for setting up a spot by the door with everything needed for leaving.', 'Use it to help a client cut down the scramble before leaving the house.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through the client''s usual exits and list what gets forgotten. Set up one visible spot for keys, wallet and bag. Keep it simple and visual. Ask what usually breaks the system and plan for that. Check back in a week and move things around until it fits the client''s habits.', '[{"id": "f0", "type": "textarea", "label": "What I usually forget when I leave"}, {"id": "f1", "type": "textarea", "label": "What I need at the launch pad"}, {"id": "f2", "type": "textarea", "label": "Where the launch pad will go"}, {"id": "f3", "type": "textarea", "label": "What usually breaks my system"}, {"id": "f4", "type": "textarea", "label": "How I will remember to use it"}]'::jsonb, array['ADHD', 'routines', 'planning']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('task-starting-barriers-log', 'Task Starting Barriers Log', 'cbt'::resource_kind, 'A log of what gets in the way of starting a task and the smallest first move.', 'Use it to help a client see the barrier to starting and shrink the first step.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log tasks they put off and what felt hard about the start. Look for patterns like unclear first steps or boredom. Pair each barrier with a tiny first move of two minutes or less. Avoid framing delay as a character flaw. Review which first moves actually got things going.', '[{"id": "f0", "type": "textarea", "label": "The task I put off"}, {"id": "f1", "type": "textarea", "label": "What made it hard to start"}, {"id": "f2", "type": "textarea", "label": "The first two-minute move"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['ADHD', 'planning', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('values-behind-the-pile-sorting-sheet', 'Values Behind the Pile Sorting Sheet', 'act'::resource_kind, 'A sheet that links neglected tasks to the values behind them to build motivation.', 'Use it to help a client reconnect with why a task matters before they start it.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a task that has been sitting, then ask what value it serves, such as care for family or financial peace. Writing the reason can lift the dread. Keep it short. Pair it with a small action step and a time. Do not use values as a stick; the aim is meaning.', '[{"id": "f0", "type": "textarea", "label": "A task that has been waiting"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "What my mind says about starting"}, {"id": "f3", "type": "textarea", "label": "The tiny step I will take today"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}]'::jsonb, array['ADHD', 'values', 'committed action']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('household-rhythm-agreement-for-two', 'Household Rhythm Agreement for Two', 'couples'::resource_kind, 'A weekly agreement on who does what and when, with reminders chosen by the person doing it.', 'Use it to help a couple share household tasks without nagging or resentment.', array['Couples']::text[], '30 minutes', 'Each partner lists tasks they can own and how they want to be reminded. The reminder should come from the doer''s system, not the partner''s voice. Check fairness of effort together. Revisit after two weeks and renegotiate. Name strengths of each partner too so it does not become a list of faults.', '[{"id": "f0", "type": "textarea", "label": "Tasks Partner A will own"}, {"id": "f1", "type": "textarea", "label": "Tasks Partner B will own"}, {"id": "f2", "type": "textarea", "label": "How each of us wants to be reminded"}, {"id": "f3", "type": "textarea", "label": "What we do when a task slips"}, {"id": "f4", "type": "textarea", "label": "When we will review this agreement"}]'::jsonb, array['ADHD', 'couples', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('focus-mission-control-board-craft', 'Focus Mission Control Board Craft', 'kids'::resource_kind, 'A craft board where a child sets out a mission with steps and a timer.', 'Use it to help a child break a task into steps they can see and tick off.', array['Children']::text[], '30 minutes', 'Build the board with pictures for each step and a sand timer or kitchen timer. The child picks a mission, like getting ready for school, and moves a marker along. Parent role: set the board up, cheer progress, and keep reminders to a single prompt. Adjust the steps if the child gets stuck at one.', '[{"id": "f0", "type": "textarea", "label": "My mission"}, {"id": "f1", "type": "textarea", "label": "The steps on my board"}, {"id": "f2", "type": "textarea", "label": "How long my timer runs"}, {"id": "f3", "type": "textarea", "label": "What helps me keep going"}, {"id": "f4", "type": "textarea", "label": "What my parent does to help"}]'::jsonb, array['ADHD', 'kids', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('urge-wave-surfing-log', 'Urge Wave Surfing Log', 'worksheet'::resource_kind, 'A log of an urge from rise to peak to fade, with what the client did while it passed.', 'Use it to help a client see that urges rise and fall and that they can ride one out.', array['Adults']::text[], 'One week', 'Ask the client to record the time, the urge strength and what they did to ride it out. Use their own words for urges and substance use. Review the log for what made the wave shorter or easier. Do not frame a lapse as failure; look at what the log shows about triggers and supports.', '[{"id": "f0", "type": "textarea", "label": "What set off the urge"}, {"id": "f1", "type": "textarea", "label": "Strength at the start, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I did while it passed"}, {"id": "f3", "type": "textarea", "label": "Strength after, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What helped most"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('substance-use-chain-analysis-sheet', 'Substance Use Chain Analysis Sheet', 'cbt'::resource_kind, 'A step-by-step sheet tracing the links before and after a moment of substance use.', 'Use it to help a client find where in the chain a different choice was possible.', array['Adults']::text[], '30 minutes', 'Walk through one recent moment from the earliest trigger forward, without shame. Mark the links where something else could have happened. The aim is a clearer map, not blame. Pick one link to practice changing. Use plain words like substance use and urges.', '[{"id": "f0", "type": "textarea", "label": "The earliest trigger I can see"}, {"id": "f1", "type": "textarea", "label": "The thoughts and urges that followed"}, {"id": "f2", "type": "textarea", "label": "What I did next"}, {"id": "f3", "type": "textarea", "label": "What happened afterward"}, {"id": "f4", "type": "textarea", "label": "A link where I could try something else"}]'::jsonb, array['addiction', 'core CBT', 'urges']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('urge-surfing-with-values-anchor-practice', 'Urge Surfing With Values Anchor Practice', 'act'::resource_kind, 'A practice that pairs noticing an urge with a reminder of what the client cares about.', 'Use it to help a client stay with an urge while keeping a value in view.', array['Adults']::text[], '20 minutes', 'Describe the urge as a wave with a rising, peak and fade. The client names a value they want to protect, such as trust or health, and holds it in mind during the practice. Rehearse in session with a mild urge. Keep language about substance use matter-of-fact.', '[{"id": "f0", "type": "textarea", "label": "The urge I am noticing"}, {"id": "f1", "type": "textarea", "label": "Where I feel it in my body"}, {"id": "f2", "type": "textarea", "label": "The value I want to keep in view"}, {"id": "f3", "type": "textarea", "label": "What I do while it passes"}, {"id": "f4", "type": "textarea", "label": "What I notice when it fades"}]'::jsonb, array['addiction', 'core ACT', 'urges', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('urge-skills-menu-by-length-of-wave', 'Urge Skills Menu by Length of Wave', 'dbt'::resource_kind, 'A menu of distress tolerance skills grouped by how long the urge may last.', 'Use it to help a client pick a skill that fits how intense and how long an urge is.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort skills into quick (cold water, paced breathing), medium (a walk, calling someone) and longer (an activity or meeting). The client rates which they would really use. Add a contact for support. Review which items worked and replace the ones that did not.', '[{"id": "f0", "type": "textarea", "label": "Quick skills I could use in a minute"}, {"id": "f1", "type": "textarea", "label": "Medium skills for twenty minutes"}, {"id": "f2", "type": "textarea", "label": "Longer skills for a rough evening"}, {"id": "f3", "type": "textarea", "label": "A person I can contact"}, {"id": "f4", "type": "textarea", "label": "The skill I will try first"}]'::jsonb, array['addiction', 'core DBT', 'urges', 'distress tolerance']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('trigger-cards-and-coping-moves-game', 'Trigger Cards and Coping Moves Game', 'game'::resource_kind, 'Players draw a trigger card and name a coping move, with the group adding another.', 'Use it to help a group build a shared list of coping moves for common triggers.', array['Adults', 'Groups']::text[], '30 minutes', 'Rules: draw a trigger card, say what you would do, and the group adds one more idea. Turns rotate and anyone can pass. Keep cards general, like a stressful day or an old route. Debrief on which moves people want to try and what was surprising. Use language about substance use and urges.', '[{"id": "f0", "type": "textarea", "label": "The trigger I drew"}, {"id": "f1", "type": "textarea", "label": "The coping move I said"}, {"id": "f2", "type": "textarea", "label": "A move from the group I liked"}, {"id": "f3", "type": "textarea", "label": "The move I will try this week"}]'::jsonb, array['addiction', 'game', 'urges', 'group']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anger-early-warning-signs-body-map', 'Anger Early Warning Signs Body Map', 'worksheet'::resource_kind, 'A body map for marking where anger starts to build before it boils over.', 'Use it to help a client catch anger early, when they have more choices.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client color or mark the places they feel anger rising, in order. Ask about heat, tight jaw, fast breath. Then match each early sign with a pause skill. Practice noticing the first sign in session. Keep it about the body, not about what the other person did.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first"}, {"id": "f1", "type": "textarea", "label": "The signs that come next"}, {"id": "f2", "type": "textarea", "label": "The point where it gets hard to stop"}, {"id": "f3", "type": "textarea", "label": "A pause I can use at the first sign"}, {"id": "f4", "type": "textarea", "label": "Who can help me notice"}]'::jsonb, array['anger management', 'regulation', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anger-trigger-thought-rewrite-sheet', 'Anger Trigger Thought Rewrite Sheet', 'cbt'::resource_kind, 'A sheet that catches the hot thoughts that feed anger and tries out more balanced ones.', 'Use it to help a client find the thought that lit the fuse and try another.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recent episode and ask what the client told themselves in the moment. Look for should statements and mind reading. Draft a more balanced thought without arguing the anger away. Practice saying it. Check how much the anger drops, not whether it disappears.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I told myself"}, {"id": "f2", "type": "textarea", "label": "How angry I was, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}, {"id": "f4", "type": "textarea", "label": "How angry I am now"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anger-underneath-feelings-dig-sheet', 'Anger Underneath Feelings Dig Sheet', 'act'::resource_kind, 'A sheet for looking beneath anger to the feelings and values that sit under it.', 'Use it to help a client see what anger is protecting and what they want instead.', array['Adults', 'Teens']::text[], '25 minutes', 'Anger often covers hurt, fear or shame. Ask gently what sits under it and what the client cares about in the situation. Connect that to a values-based action. Avoid naming the underlying feeling for them. Let them find it, and give time.', '[{"id": "f0", "type": "textarea", "label": "The situation that made me angry"}, {"id": "f1", "type": "textarea", "label": "What I feel under the anger"}, {"id": "f2", "type": "textarea", "label": "What I care about here"}, {"id": "f3", "type": "textarea", "label": "What I want to do that fits what I care about"}, {"id": "f4", "type": "textarea", "label": "A first step I can take"}]'::jsonb, array['anger management', 'core ACT', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('cool-down-skill-kit-builder', 'Cool-Down Skill Kit Builder', 'dbt'::resource_kind, 'A guide to assembling a small kit of cool-down skills for the moments after anger spikes.', 'Use it to help a client prepare a kit of calming skills before they need them.', array['Adults', 'Teens']::text[], '25 minutes', 'List sensory skills across sight, sound, touch and movement and let the client pick a few for a physical or digital kit. Rehearse using one. Suggest a time-out plan agreed with family. Review what the client actually used and replace what they did not.', '[{"id": "f0", "type": "textarea", "label": "Skills for my body"}, {"id": "f1", "type": "textarea", "label": "Skills for my senses"}, {"id": "f2", "type": "textarea", "label": "Skills that involve other people"}, {"id": "f3", "type": "textarea", "label": "What goes in my kit"}, {"id": "f4", "type": "textarea", "label": "When I will use it this week"}]'::jsonb, array['anger management', 'core DBT', 'self-soothing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-craft-with-parent-plan', 'Anger Thermometer Craft With Parent Plan', 'kids'::resource_kind, 'A thermometer craft where a child marks anger levels and picks a calming move for each.', 'Use it to help a child notice anger rising and pick a calming move before it peaks.', array['Children']::text[], '25 minutes', 'Build the thermometer from paper and have the child choose colors for each level and a move for each. Parent role: learn the moves, remind the child gently, and stay calm yourself. Practice at a low level first. Reporting duties apply if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What each level feels like"}, {"id": "f1", "type": "textarea", "label": "A calming move for each level"}, {"id": "f2", "type": "textarea", "label": "Who helps me use them"}, {"id": "f3", "type": "textarea", "label": "What I want my parent to say to me"}, {"id": "f4", "type": "textarea", "label": "Where our thermometer lives"}]'::jsonb, array['anger management', 'kids', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('doubt-loop-map-and-exit-points', 'Doubt Loop Map and Exit Points', 'worksheet'::resource_kind, 'A map of how a doubt loops through urges and rituals and where the client can step out.', 'Use it to help a client see the loop and choose a point to step out of it.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the loop with the client: intrusive thought, distress, urge, ritual, brief relief, doubt returns. Mark exit points. Do not offer reassurance within the session as it can feed the loop. Pick one exit point to try this week at a small step and plan support for it.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought or doubt"}, {"id": "f1", "type": "textarea", "label": "The urge that follows"}, {"id": "f2", "type": "textarea", "label": "What I do to feel certain"}, {"id": "f3", "type": "textarea", "label": "How long the relief lasts"}, {"id": "f4", "type": "textarea", "label": "An exit point I could try"}]'::jsonb, array['OCD', 'exposure', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('ritual-delay-timer-log', 'Ritual Delay Timer Log', 'cbt'::resource_kind, 'A log for delaying a ritual a few minutes longer each time and recording what happens.', 'Use it to help a client build tolerance for the urge by waiting before acting on it.', array['Adults', 'Teens']::text[], 'Two weeks', 'Agree on a small delay, such as two minutes, and increase gradually. The client logs the urge, how long they waited and what happened to the distress. Be clear the goal is gradual practice, not perfect resistance. Celebrate any delay. Plan the next step based on the log.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed"}, {"id": "f1", "type": "textarea", "label": "How long I waited"}, {"id": "f2", "type": "textarea", "label": "Distress at the start, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Distress at the end, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I will do next time"}]'::jsonb, array['OCD', 'exposure', 'core CBT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('unwelcome-guest-intrusive-thoughts-defusion-sheet', 'Unwelcome Guest Intrusive Thoughts Defusion Sheet', 'act'::resource_kind, 'A sheet that treats an intrusive thought like an unwelcome guest who can be noticed without being obeyed.', 'Use it to help a client let intrusive thoughts be present while they do what matters.', array['Adults', 'Teens']::text[], '20 minutes', 'Offer the guest metaphor and let the client adapt it. The goal is not to push the thought away but to carry on with a valued activity while it visits. Ask what the guest says and what the client does anyway. Avoid arguing about content; stay with the relationship to the thought.', '[{"id": "f0", "type": "textarea", "label": "The unwelcome thought that shows up"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I do while it visits"}, {"id": "f3", "type": "textarea", "label": "A value I can act on anyway"}, {"id": "f4", "type": "textarea", "label": "A phrase to remind me it is a thought"}]'::jsonb, array['OCD', 'core ACT', 'defusion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('sitting-with-uncertainty-self-soothe-plan', 'Sitting With Uncertainty Self-Soothe Plan', 'dbt'::resource_kind, 'A plan for soothing the body while uncertainty stays unresolved.', 'Use it to help a client soothe themselves without needing certainty first.', array['Adults', 'Teens']::text[], '20 minutes', 'Pair uncertainty with senses-based soothing, such as warm tea, texture or music. The client practices soothing alongside the uncertainty instead of waiting for it to be solved. Remind them this is not avoidance but care. Review which soothing choices were realistic.', '[{"id": "f0", "type": "textarea", "label": "A moment of uncertainty I face"}, {"id": "f1", "type": "textarea", "label": "Soothing ideas for my senses"}, {"id": "f2", "type": "textarea", "label": "What I can do while the doubt stays"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to"}, {"id": "f4", "type": "textarea", "label": "What I noticed after"}]'::jsonb, array['OCD', 'core DBT', 'self-soothing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('family-accommodation-check-in-for-partners', 'Family Accommodation Check-In for Partners', 'couples'::resource_kind, 'A conversation sheet for partners to review how they adjust routines around rituals.', 'Use it to help a couple find supportive ways to respond without joining the rituals.', array['Couples']::text[], '30 minutes', 'Invite the partner to name what they change in daily life and how it feels. The client says which help is welcome. Together plan gentle shifts and what the partner can say. Keep tone kind and avoid blame. Revisit often as the client takes steps.', '[{"id": "f0", "type": "textarea", "label": "Ways my partner adjusts for the rituals"}, {"id": "f1", "type": "textarea", "label": "How that feels for each of us"}, {"id": "f2", "type": "textarea", "label": "What support the client wants"}, {"id": "f3", "type": "textarea", "label": "A kind phrase we can use"}, {"id": "f4", "type": "textarea", "label": "What we will try this week"}]'::jsonb, array['OCD', 'couples', 'support']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('panic-wave-rating-chart', 'Panic Wave Rating Chart', 'worksheet'::resource_kind, 'A chart tracking the rise, peak and fall of a panic wave with what the client did.', 'Use it to help a client see that a panic wave passes and what helps it pass.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to rate intensity every few minutes during a wave if they can, or recall afterward. Review the shape: rise, peak, fall. Highlight what they did that helped. Avoid reassurance that it will never happen again. The goal is familiarity with the shape.', '[{"id": "f0", "type": "textarea", "label": "Where I was when it began"}, {"id": "f1", "type": "textarea", "label": "Intensity at the start, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Peak intensity and how long it lasted"}, {"id": "f3", "type": "textarea", "label": "What I did as it passed"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the shape"}]'::jsonb, array['panic attacks', 'self-monitoring', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('body-sensation-interpretation-sort', 'Body Sensation Interpretation Sort', 'cbt'::resource_kind, 'A sort of what the client thought a sensation meant versus other possible explanations.', 'Use it to help a client consider other explanations for strong body sensations.', array['Adults', 'Teens']::text[], '25 minutes', 'List sensations in a column, then the feared meaning and other possible explanations such as breath rate or caffeine. Do not reassure; invite the client to weigh options. Refer medical questions to a physician. Review which alternate explanations felt believable.', '[{"id": "f0", "type": "textarea", "label": "A sensation I noticed"}, {"id": "f1", "type": "textarea", "label": "What I feared it meant"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations"}, {"id": "f3", "type": "textarea", "label": "How much I believe each one"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself next time"}]'::jsonb, array['panic attacks', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-it-panic-practice-page', 'Willing to Feel It Panic Practice Page', 'act'::resource_kind, 'A page for allowing sensations to come and go while doing something that matters.', 'Use it to help a client stay in a valued activity while sensations rise.', array['Adults']::text[], '25 minutes', 'Choose a small valued activity and plan to do it while sensations are present. Teach the client to notice sensations like weather and not fight them. Rehearse in session with a mild sensation. Review what they did when the sensations rose and what the activity meant to them.', '[{"id": "f0", "type": "textarea", "label": "The activity I want to do"}, {"id": "f1", "type": "textarea", "label": "The sensations I expect"}, {"id": "f2", "type": "textarea", "label": "How I will make room for them"}, {"id": "f3", "type": "textarea", "label": "What I will do if they rise"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-grounding-combo-card', 'Paced Breathing and Grounding Combo Card', 'dbt'::resource_kind, 'A card combining paced breathing with grounding steps for the middle of a wave.', 'Use it to help a client use two simple skills together during a panic wave.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice slow exhale breathing and naming five things seen in session so the card is familiar. Keep the card short enough to read in the middle of a wave. Some clients feel worse with breath focus; offer sensory grounding only as an alternative. Review how it worked.', '[{"id": "f0", "type": "textarea", "label": "My breathing count"}, {"id": "f1", "type": "textarea", "label": "Five things I can see"}, {"id": "f2", "type": "textarea", "label": "The sensation I notice most"}, {"id": "f3", "type": "textarea", "label": "What helps me stay with it"}, {"id": "f4", "type": "textarea", "label": "When I will practice"}]'::jsonb, array['panic attacks', 'core DBT', 'grounding']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('volcano-feelings-bubble-breathing-craft', 'Volcano Feelings Bubble Breathing Craft', 'kids'::resource_kind, 'A craft pairing a volcano drawing with bubble breathing for sudden big body feelings.', 'Use it to help a child learn that big body feelings rise, peak and settle.', array['Children']::text[], '25 minutes', 'Draw a volcano with the child and add small bubbles by blowing slowly. Explain that the feeling rises, peaks and settles. A parent learns the slow breath and does it with them. Keep the craft available at home. If a child has frequent episodes, the parent should speak with the child''s doctor.', '[{"id": "f0", "type": "textarea", "label": "What my volcano looks like"}, {"id": "f1", "type": "textarea", "label": "What my body feels when it rises"}, {"id": "f2", "type": "textarea", "label": "How I blow bubbles slowly"}, {"id": "f3", "type": "textarea", "label": "Who sits with me"}, {"id": "f4", "type": "textarea", "label": "Where we keep the bubbles"}]'::jsonb, array['panic attacks', 'kids', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('rupture-and-repair-parent-reflection-page', 'Rupture and Repair Parent Reflection Page', 'worksheet'::resource_kind, 'A page for reflecting on a hard moment with a child and planning a repair.', 'Use it to help a parent see repair as a normal part of parenting.', array['Adults']::text[], '20 minutes', 'Pick a recent moment the parent regrets and look at it with kindness. Plan what they might say to their child. Emphasize that repair matters more than perfection. Role-play the words. Avoid shaming language and keep the focus on what the parent can do next.', '[{"id": "f0", "type": "textarea", "label": "The moment I wish had gone differently"}, {"id": "f1", "type": "textarea", "label": "What I was feeling"}, {"id": "f2", "type": "textarea", "label": "What my child may have felt"}, {"id": "f3", "type": "textarea", "label": "What I could say to repair"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}]'::jsonb, array['parenting', 'communication', 'self-compassion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-before-reacting-sheet', 'Parent Thought Check Before Reacting Sheet', 'cbt'::resource_kind, 'A sheet for checking the thought behind a reaction before responding to a child.', 'Use it to help a parent notice the thought that fuels a reaction and choose a response.', array['Adults']::text[], '20 minutes', 'Ask what the parent tells themselves when the child misbehaves, such as "they are doing this to me." Draft a more balanced thought and a response that fits their values. Practice in session. The sheet works best when filled in after an episode, then used in the moment.', '[{"id": "f0", "type": "textarea", "label": "What my child did"}, {"id": "f1", "type": "textarea", "label": "What I told myself"}, {"id": "f2", "type": "textarea", "label": "How I reacted"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}, {"id": "f4", "type": "textarea", "label": "What I would like to do"}]'::jsonb, array['parenting', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('parent-values-compass-for-hard-seasons', 'Parent Values Compass for Hard Seasons', 'act'::resource_kind, 'A compass sheet connecting parenting values with small daily acts.', 'Use it to help a parent stay connected to the kind of parent they want to be.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent they hope to be and what a child would say about them. Connect values to small acts like bedtime talk or listening first. Accept that hard seasons happen. The sheet helps return to values after a rough day.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A small act that fits it"}, {"id": "f2", "type": "textarea", "label": "What gets in the way"}, {"id": "f3", "type": "textarea", "label": "How I can return to it after a hard day"}, {"id": "f4", "type": "textarea", "label": "One act I will do this week"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('co-parent-check-in-meeting-agenda', 'Co-Parent Check-In Meeting Agenda', 'couples'::resource_kind, 'An agenda for a short weekly meeting between co-parents.', 'Use it to help co-parents coordinate and support each other.', array['Couples']::text[], '30 minutes', 'Set a short regular time away from the children. Agenda: what went well, what is coming up, one thing each needs from the other, one thing to appreciate. Avoid turning it into a complaint session. Review in session whether the meeting happened and what made it work.', '[{"id": "f0", "type": "textarea", "label": "What went well this week"}, {"id": "f1", "type": "textarea", "label": "What is coming up for the kids"}, {"id": "f2", "type": "textarea", "label": "What I need from my co-parent"}, {"id": "f3", "type": "textarea", "label": "Something I appreciate"}, {"id": "f4", "type": "textarea", "label": "What we will try next week"}]'::jsonb, array['parenting', 'couples', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('parent-pause-role-play-card-game', 'Parent Pause Role-Play Card Game', 'game'::resource_kind, 'Parents draw scenario cards and rehearse a pause and response, with the group giving feedback.', 'Use it to help parents practice a pause in low-stakes rounds.', array['Adults', 'Groups']::text[], '30 minutes', 'Rules: draw a card with a common scene, like refusing to leave the park. Take turns saying what you would do and the group adds ideas. Anyone can pass. Debrief on which pauses felt realistic. Keep it supportive and avoid judging how any parent responds.', '[{"id": "f0", "type": "textarea", "label": "The scene I drew"}, {"id": "f1", "type": "textarea", "label": "My pause and response"}, {"id": "f2", "type": "textarea", "label": "An idea from the group I liked"}, {"id": "f3", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'game', 'group', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('newborn-weeks-helper-circles-map', 'Newborn Weeks Helper Circles Map', 'worksheet'::resource_kind, 'A map of who can help with what in the weeks after a baby arrives.', 'Use it to help a new parent line up practical and emotional support.', array['Adults']::text[], '25 minutes', 'Sketch circles of support: partner, family, friends, professionals. List concrete tasks each person could take. Many parents find it hard to ask. Role-play requests. Include contacts for questions to their medical providers and the 988 Suicide and Crisis Lifeline (call or text 988) for urgent distress.', '[{"id": "f0", "type": "textarea", "label": "People closest to me and what they could do"}, {"id": "f1", "type": "textarea", "label": "Practical help I need"}, {"id": "f2", "type": "textarea", "label": "Emotional support I need"}, {"id": "f3", "type": "textarea", "label": "Who I will ask first"}, {"id": "f4", "type": "textarea", "label": "If things feel urgent: 988 (call or text)"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('perfect-parent-thought-balance-sheet', 'Perfect Parent Thought Balance Sheet', 'cbt'::resource_kind, 'A sheet that tests the thought "I should be doing this perfectly" against more balanced versions.', 'Use it to help a new parent loosen unrealistic standards.', array['Adults']::text[], '25 minutes', 'Ask what the parent believes a good parent does. Look for always and never language. Draft kinder standards. Be warm; many parents have little sleep and high pressure. Keep a short list of balanced thoughts to read on hard nights.', '[{"id": "f0", "type": "textarea", "label": "The standard I hold myself to"}, {"id": "f1", "type": "textarea", "label": "What I tell myself when I miss it"}, {"id": "f2", "type": "textarea", "label": "A kinder version"}, {"id": "f3", "type": "textarea", "label": "What a friend would say"}, {"id": "f4", "type": "textarea", "label": "The balanced thought I will keep"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('sleepless-night-acceptance-and-values-page', 'Sleepless Night Acceptance and Values Page', 'act'::resource_kind, 'A page for getting through nights with limited sleep while holding onto what matters.', 'Use it to help a parent make room for tiredness and stay close to their values.', array['Adults']::text[], '20 minutes', 'Acknowledge how tiring this is. The client names small valued acts, like a gentle word to the baby, that are possible on little sleep. Accept that feelings will come. Plan a small break each day. Encourage them to talk with their provider about sleep and mood.', '[{"id": "f0", "type": "textarea", "label": "What the nights are like"}, {"id": "f1", "type": "textarea", "label": "What I feel when I am tired"}, {"id": "f2", "type": "textarea", "label": "A value I can act on even when tired"}, {"id": "f3", "type": "textarea", "label": "A small break I can take today"}, {"id": "f4", "type": "textarea", "label": "Who I can ask for help"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'acceptance']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('overwhelm-skills-card-for-the-early-weeks', 'Overwhelm Skills Card for the Early Weeks', 'dbt'::resource_kind, 'A skills card with quick regulation steps for moments of overwhelm with a newborn.', 'Use it to help a new parent steady themselves in the middle of a hard moment.', array['Adults']::text[], '15 minutes', 'Choose quick skills that can be done holding a baby: paced breath, cold water on the wrists, naming five things seen. Practice one in session. Include a plan for safely setting the baby down if needed and reaching out for support.', '[{"id": "f0", "type": "textarea", "label": "What overwhelm feels like for me"}, {"id": "f1", "type": "textarea", "label": "Quick skills I can do with a baby"}, {"id": "f2", "type": "textarea", "label": "A safe place to set the baby down"}, {"id": "f3", "type": "textarea", "label": "A person I can call"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'regulation']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('night-shift-handoff-plan-for-two', 'Night Shift Handoff Plan for Two', 'couples'::resource_kind, 'A plan for sharing night care and protecting each partner''s rest.', 'Use it to help a couple share the night load and protect sleep.', array['Couples']::text[], '30 minutes', 'Map the night and trade tasks so each partner gets a longer stretch of sleep when possible. Name feelings of resentment openly. Include a kind phrase for handoffs. Revisit weekly as the baby''s needs change.', '[{"id": "f0", "type": "textarea", "label": "Night tasks and who takes which"}, {"id": "f1", "type": "textarea", "label": "Each partner''s protected sleep stretch"}, {"id": "f2", "type": "textarea", "label": "What helps us hand off kindly"}, {"id": "f3", "type": "textarea", "label": "What we need from each other"}, {"id": "f4", "type": "textarea", "label": "When we will adjust the plan"}]'::jsonb, array['perinatal and postpartum', 'couples', 'routines']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('evidence-folder-for-self-worth', 'Evidence Folder for Self-Worth', 'worksheet'::resource_kind, 'A folder-style sheet for collecting real moments that speak against harsh self-judgments.', 'Use it to help a client gather lived evidence that complicates a harsh self-view.', array['Adults', 'Teens']::text[], 'One week', 'Ask for daily entries of something done, a kind word received or an effort made. Use observable facts. At review, read them aloud and notice what the client resists. Avoid pushing a positive spin; the aim is a more accurate view.', '[{"id": "f0", "type": "textarea", "label": "A harsh thing I tell myself"}, {"id": "f1", "type": "textarea", "label": "Something I did today"}, {"id": "f2", "type": "textarea", "label": "A kind word or moment I noticed"}, {"id": "f3", "type": "textarea", "label": "What this says that the harsh view leaves out"}, {"id": "f4", "type": "textarea", "label": "What I want to remember"}]'::jsonb, array['self-esteem', 'strengths', 'core CBT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('inner-critic-fact-versus-opinion-sort', 'Inner Critic Fact Versus Opinion Sort', 'cbt'::resource_kind, 'A sort of critic statements into facts and opinions.', 'Use it to help a client see which self-critical statements are facts and which are opinions.', array['Adults', 'Teens']::text[], '20 minutes', 'Write critic statements on slips and sort into fact, opinion and unclear. Many turn out to be opinions stated as facts. Ask for a reworded version of the opinions. Avoid arguing; let the sorting do the work.', '[{"id": "f0", "type": "textarea", "label": "Critic statements I hear often"}, {"id": "f1", "type": "textarea", "label": "Which are facts"}, {"id": "f2", "type": "textarea", "label": "Which are opinions"}, {"id": "f3", "type": "textarea", "label": "A reworded version of one opinion"}, {"id": "f4", "type": "textarea", "label": "How it felt to sort them"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('self-worth-without-conditions-reflection', 'Self-Worth Without Conditions Reflection', 'act'::resource_kind, 'A reflection page on what it means to value oneself without earning it.', 'Use it to help a client separate their worth from performance.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask when the client feels worthy and when not. Notice the conditions attached. Explore what it might be to treat themselves as they treat a friend regardless of results. Keep concrete with one small act this week.', '[{"id": "f0", "type": "textarea", "label": "When I feel I have to earn worth"}, {"id": "f1", "type": "textarea", "label": "The conditions I have set"}, {"id": "f2", "type": "textarea", "label": "How I treat a friend who struggles"}, {"id": "f3", "type": "textarea", "label": "One thing I will do for myself without earning it"}, {"id": "f4", "type": "textarea", "label": "What I notice"}]'::jsonb, array['self-esteem', 'core ACT', 'self-compassion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('validation-practice-for-yourself', 'Validation Practice for Yourself', 'dbt'::resource_kind, 'A practice for naming what makes sense about one''s own feelings and reactions.', 'Use it to help a client offer themselves the validation they look for elsewhere.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach self-validation: find the kernel of truth, name feelings without judging, acknowledge how past experience shapes a reaction. Practice with a recent event in session. Some clients find it awkward; start with a small matter.', '[{"id": "f0", "type": "textarea", "label": "A recent feeling I judged"}, {"id": "f1", "type": "textarea", "label": "What makes sense about it"}, {"id": "f2", "type": "textarea", "label": "What past experiences shape it"}, {"id": "f3", "type": "textarea", "label": "A validating thing I can say to myself"}, {"id": "f4", "type": "textarea", "label": "How it felt"}]'::jsonb, array['self-esteem', 'core DBT', 'self-compassion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('all-about-me-shield-craft', 'All About Me Shield Craft', 'kids'::resource_kind, 'A shield with drawn sections for strengths, helpers and favorite things.', 'Use it to help a child see and show the good things about themselves.', array['Children']::text[], '30 minutes', 'Fold or draw a shield with four sections: what I am good at, what I like, who helps me, what I want to try. Parent role: add a section with something they love about the child and avoid corrections. Display the shield at home.', '[{"id": "f0", "type": "textarea", "label": "What I am good at"}, {"id": "f1", "type": "textarea", "label": "What I like"}, {"id": "f2", "type": "textarea", "label": "Who helps me"}, {"id": "f3", "type": "textarea", "label": "What I want to try"}, {"id": "f4", "type": "textarea", "label": "Where I will hang my shield"}]'::jsonb, array['self-esteem', 'kids', 'strengths']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('social-risk-ladder-with-small-rungs', 'Social Risk Ladder With Small Rungs', 'worksheet'::resource_kind, 'A ladder of social situations from least to most daunting with tiny rungs.', 'Use it to help a client plan gradual steps into feared social situations.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder together with at least eight rungs, starting very small, like a smile to a neighbor. Predict distress for each. Choose the first rung and a date. Revisit weekly and add or remove rungs. Avoid skipping up too fast.', '[{"id": "f0", "type": "textarea", "label": "Situations I avoid or dread"}, {"id": "f1", "type": "textarea", "label": "My ladder from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Predicted distress for each rung"}, {"id": "f3", "type": "textarea", "label": "The first rung and when I will do it"}, {"id": "f4", "type": "textarea", "label": "What I will do to celebrate it"}]'::jsonb, array['social anxiety', 'exposure', 'planning']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-observation-experiment', 'Spotlight Effect Observation Experiment', 'cbt'::resource_kind, 'An experiment for checking how much others actually notice the client.', 'Use it to help a client test the feeling that everyone is watching.', array['Adults', 'Teens']::text[], 'One week', 'Have the client predict how many people will notice a small thing, then observe or ask. Record what happened. Discuss the gap. Choose safe, low-risk experiments. Be clear that this is about noticing, not about being invisible.', '[{"id": "f0", "type": "textarea", "label": "What I think others will notice"}, {"id": "f1", "type": "textarea", "label": "My prediction, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'core CBT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('social-anxiety-and-values-in-company-sheet', 'Social Anxiety and Values in Company Sheet', 'act'::resource_kind, 'A sheet for choosing a value to guide a social moment even when nervous.', 'Use it to help a client go toward people in a way that fits their values.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick a value like curiosity or kindness and an upcoming moment. The client decides what it would look like and how to carry nerves along. Practice in session. Check afterward what the value made possible.', '[{"id": "f0", "type": "textarea", "label": "A social moment coming up"}, {"id": "f1", "type": "textarea", "label": "A value I want to bring"}, {"id": "f2", "type": "textarea", "label": "What it looks like in action"}, {"id": "f3", "type": "textarea", "label": "What my nerves may say"}, {"id": "f4", "type": "textarea", "label": "What I will do anyway"}]'::jsonb, array['social anxiety', 'core ACT', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('interpersonal-rehearsal-for-starting-a-conversation', 'Interpersonal Rehearsal for Starting a Conversation', 'dbt'::resource_kind, 'A rehearsal sheet using DBT interpersonal skills to start and end small talk.', 'Use it to help a client rehearse the words for beginning and ending a conversation.', array['Adults', 'Teens']::text[], '25 minutes', 'Role-play openers, questions and ways to leave politely. Use the GIVE steps for warmth and DEAR MAN for requests if needed. Write short lines on a card. Review how it went and adjust.', '[{"id": "f0", "type": "textarea", "label": "An opener I could use"}, {"id": "f1", "type": "textarea", "label": "A question I can ask"}, {"id": "f2", "type": "textarea", "label": "A kind way to end the conversation"}, {"id": "f3", "type": "textarea", "label": "What I will do if I freeze"}, {"id": "f4", "type": "textarea", "label": "When I will try it"}]'::jsonb, array['social anxiety', 'core DBT', 'interpersonal effectiveness']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('small-talk-dice-group-game', 'Small Talk Dice Group Game', 'game'::resource_kind, 'Players roll dice to pick a small-talk prompt and practice answering and asking.', 'Use it to help a group practice casual conversation in a safe setting.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Rules: roll a die, match the number to a prompt like weekend plans, answer in a sentence or two, and ask one question back. Turns go around the circle; passing is allowed. Debrief on what felt easier than expected and what the group noticed.', '[{"id": "f0", "type": "textarea", "label": "The prompt I rolled"}, {"id": "f1", "type": "textarea", "label": "My answer"}, {"id": "f2", "type": "textarea", "label": "A question I asked back"}, {"id": "f3", "type": "textarea", "label": "What felt easier than expected"}]'::jsonb, array['social anxiety', 'game', 'group', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('grief-waves-daily-notes-page', 'Grief Waves Daily Notes Page', 'worksheet'::resource_kind, 'A page for noting when grief rises, what brings it, and what helps.', 'Use it to help a client see the rhythm of their grief and what supports them through it.', array['Adults', 'Teens']::text[], 'One week', 'Invite brief entries, a few lines at most. Note the time, what set it off and what helped. Reassure the client that waves come and go and that there is no schedule. Review for patterns and for the small comforts that worked.', '[{"id": "f0", "type": "textarea", "label": "When grief rose today"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What helped a little"}, {"id": "f3", "type": "textarea", "label": "What I needed and did not get"}, {"id": "f4", "type": "textarea", "label": "One small comfort for tomorrow"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('unfinished-business-letter-planning-sheet', 'Unfinished Business Letter Planning Sheet', 'cbt'::resource_kind, 'A sheet for planning a letter to someone who died, kept in session and sized to the client.', 'Use it to help a client put words to what was left unsaid at a pace that feels bearable.', array['Adults', 'Teens']::text[], '30 minutes', 'Plan the letter together: who it is to, what to say, and how long to write. Write it in session or with a support person present. The client decides whether to keep, read aloud or put it away. Stop if it is too much.', '[{"id": "f0", "type": "textarea", "label": "Who the letter is to"}, {"id": "f1", "type": "textarea", "label": "What I want them to know"}, {"id": "f2", "type": "textarea", "label": "What I wish I had said"}, {"id": "f3", "type": "textarea", "label": "Who will be with me when I write it"}, {"id": "f4", "type": "textarea", "label": "What I will do with the letter"}]'::jsonb, array['grief and loss', 'core CBT', 'support']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('carrying-love-and-loss-together-values-sheet', 'Carrying Love and Loss Together Values Sheet', 'act'::resource_kind, 'A sheet on how love and grief live together and what the client wants to carry forward.', 'Use it to help a client honor what mattered about the person while living their own life.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to name what the person valued and what they want to carry forward. Grief and love are two sides of the same thing. Plan a small act that honors it. Allow tears and silences.', '[{"id": "f0", "type": "textarea", "label": "What mattered about the person"}, {"id": "f1", "type": "textarea", "label": "What I want to carry forward"}, {"id": "f2", "type": "textarea", "label": "Where grief shows up when I do that"}, {"id": "f3", "type": "textarea", "label": "A small act to honor them"}, {"id": "f4", "type": "textarea", "label": "Who I will share it with"}]'::jsonb, array['grief and loss', 'core ACT', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('self-soothing-kit-for-anniversary-days', 'Self-Soothing Kit for Anniversary Days', 'dbt'::resource_kind, 'A kit plan for days that carry extra weight, such as birthdays or holidays.', 'Use it to help a client prepare for hard dates with comfort and support.', array['Adults', 'Teens']::text[], '25 minutes', 'List the dates that matter and plan ahead for each: who to be with, what to eat or wear, what to skip. Include senses-based comfort. Review afterward what helped and adjust for next time.', '[{"id": "f0", "type": "textarea", "label": "Dates that are hard for me"}, {"id": "f1", "type": "textarea", "label": "What I want to do or avoid"}, {"id": "f2", "type": "textarea", "label": "Comforts for my senses"}, {"id": "f3", "type": "textarea", "label": "People I want near"}, {"id": "f4", "type": "textarea", "label": "A plan for the evening"}]'::jsonb, array['grief and loss', 'core DBT', 'self-soothing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('memory-box-for-someone-i-miss', 'Memory Box for Someone I Miss', 'kids'::resource_kind, 'A decorated box where a child keeps drawings, photos and small treasures about a loved one.', 'Use it to help a child keep memories close and talk about the person they miss.', array['Children']::text[], '30 minutes', 'Let the child decorate a box and fill it with drawings, photos or objects. Parent role: share a favorite memory and listen without hurrying. Honor whatever the child wants to include. Reporting duties apply if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Who my box is for"}, {"id": "f1", "type": "textarea", "label": "Things I put inside"}, {"id": "f2", "type": "textarea", "label": "A favorite memory"}, {"id": "f3", "type": "textarea", "label": "How I feel when I look in it"}, {"id": "f4", "type": "textarea", "label": "Who I show it to"}]'::jsonb, array['grief and loss', 'kids', 'art']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('relationship-patterns-looping-map', 'Relationship Patterns Looping Map', 'worksheet'::resource_kind, 'A map of a repeated pattern in relationships, from trigger to reaction to result.', 'Use it to help a client spot a pattern and choose where to change it.', array['Adults']::text[], '30 minutes', 'Pick one recurring pattern and draw it. Ask what each person in it feels and needs. Look for the point where the client has some say. Pick one different move to try and plan for the discomfort that comes with it.', '[{"id": "f0", "type": "textarea", "label": "The pattern I notice"}, {"id": "f1", "type": "textarea", "label": "What sets it off"}, {"id": "f2", "type": "textarea", "label": "What I do"}, {"id": "f3", "type": "textarea", "label": "What the other person does"}, {"id": "f4", "type": "textarea", "label": "A different move I could try"}]'::jsonb, array['relationship issues', 'communication', 'self-monitoring']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('assumptions-about-closeness-check-sheet', 'Assumptions About Closeness Check Sheet', 'cbt'::resource_kind, 'A sheet for checking beliefs about intimacy and independence.', 'Use it to help a client examine the rules they hold about closeness.', array['Adults']::text[], '25 minutes', 'List beliefs like "If I need someone, I will be a burden." Ask where they came from, and test them with small behavioral experiments. Keep curious. Choose one belief to loosen.', '[{"id": "f0", "type": "textarea", "label": "A belief about closeness I hold"}, {"id": "f1", "type": "textarea", "label": "Where it came from"}, {"id": "f2", "type": "textarea", "label": "Evidence for and against"}, {"id": "f3", "type": "textarea", "label": "A small test I could try"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['relationship issues', 'core CBT', 'behavioral experiment']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('relationship-values-and-actions-check', 'Relationship Values and Actions Check', 'act'::resource_kind, 'A check on which relationship values the client is living and which are neglected.', 'Use it to help a client act on what they want to bring to their relationships.', array['Adults']::text[], '25 minutes', 'Name three values for relationships, such as honesty or warmth. Rate how much each is shown lately. Choose one action. Remind the client that values guide actions, not outcomes in others.', '[{"id": "f0", "type": "textarea", "label": "Values I want in relationships"}, {"id": "f1", "type": "textarea", "label": "How much I live each one lately"}, {"id": "f2", "type": "textarea", "label": "One I want to show more"}, {"id": "f3", "type": "textarea", "label": "A small act that shows it"}, {"id": "f4", "type": "textarea", "label": "What may get in the way"}]'::jsonb, array['relationship issues', 'values', 'core ACT']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('asking-for-what-i-need-script-builder', 'Asking for What I Need Script Builder', 'dbt'::resource_kind, 'A builder for writing and rehearsing a clear request using DEAR MAN.', 'Use it to help a client ask for what they need in a way the other person can hear.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through each step of DEAR MAN with a real request. Write a script and rehearse in session. Practice staying calm if the answer is no. Review after the conversation how it went.', '[{"id": "f0", "type": "textarea", "label": "What I want to ask for"}, {"id": "f1", "type": "textarea", "label": "Describe the situation"}, {"id": "f2", "type": "textarea", "label": "Express how I feel"}, {"id": "f3", "type": "textarea", "label": "Assert my request"}, {"id": "f4", "type": "textarea", "label": "Reinforce why it helps both of us"}]'::jsonb, array['relationship issues', 'core DBT', 'DEAR MAN']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('rebuilding-trust-small-promises-log', 'Rebuilding Trust Small Promises Log', 'couples'::resource_kind, 'A log of small promises made and kept, noted by both partners.', 'Use it to help a couple rebuild trust through small, steady actions.', array['Couples']::text[], 'One week', 'Each partner makes one or two small promises a week and tracks them. Both note what they observed. Avoid using the log as a weapon. Talk through how it felt to keep and to receive. Review pace of trust-building at each session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: promise I made"}, {"id": "f1", "type": "textarea", "label": "Partner B: promise I made"}, {"id": "f2", "type": "textarea", "label": "Whether I kept it and how it felt"}, {"id": "f3", "type": "textarea", "label": "What I noticed from my partner"}, {"id": "f4", "type": "textarea", "label": "What we will promise next week"}]'::jsonb, array['relationship issues', 'couples', 'connection']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('safety-and-support-circle-sheet', 'Safety and Support Circle Sheet', 'worksheet'::resource_kind, 'A sheet naming people and places that feel safe now and how to reach them.', 'Use it to help a client identify present-day safety and support.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep this fully in the present. Ask who feels safe and trustworthy now and how to reach them. Never ask for details of what happened. Include a place that feels safe. Review whether the circle feels right and adjust it.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to me now"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "How I can reach someone"}, {"id": "f3", "type": "textarea", "label": "Something that helps me feel steady"}, {"id": "f4", "type": "textarea", "label": "Who I will tell if I feel unsafe"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('safe-and-unsafe-today-sorting-cards', 'Safe and Unsafe Today Sorting Cards', 'cbt'::resource_kind, 'Cards for sorting today''s situations into safe, unsure or unsafe.', 'Use it to help a client check present-day safety and trust their own read.', array['Adults', 'Teens']::text[], '25 minutes', 'Use present-day situations the client brings, not the past. Sort into safe, unsure and unsafe, and talk about what helps tell the difference. Support their choice to leave any situation. Do not push for stories.', '[{"id": "f0", "type": "textarea", "label": "A situation from this week"}, {"id": "f1", "type": "textarea", "label": "Where I put it"}, {"id": "f2", "type": "textarea", "label": "What told me that"}, {"id": "f3", "type": "textarea", "label": "What I could do if I feel unsafe"}, {"id": "f4", "type": "textarea", "label": "Who I can tell"}]'::jsonb, array['sexual abuse', 'core CBT', 'safety']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('grounded-in-my-body-pacing-practice', 'Grounded in My Body Pacing Practice', 'act'::resource_kind, 'A short practice to notice the body in small steps with the option to stop at any time.', 'Use it to help a client slowly rebuild comfort in their body with control.', array['Adults', 'Teens']::text[], '15 minutes', 'Begin with something neutral like feet on the floor. The client decides how long and can stop at any point. Never push. Offer an eyes-open option. Check afterward what felt okay and what did not. Go slower if needed.', '[{"id": "f0", "type": "textarea", "label": "Where in my body feels okay"}, {"id": "f1", "type": "textarea", "label": "How long I tried"}, {"id": "f2", "type": "textarea", "label": "A signal I use to stop"}, {"id": "f3", "type": "textarea", "label": "What helped me come back"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['sexual abuse', 'core ACT', 'grounding', 'pacing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('boundary-words-practice-card', 'Boundary Words Practice Card', 'dbt'::resource_kind, 'A card of short phrases for setting and holding a boundary now.', 'Use it to help a client practice saying no and setting limits in the present.', array['Adults', 'Teens']::text[], '20 minutes', 'Rehearse short, firm phrases in session in low-stakes scenes. Let the client choose the words. Practice tone, posture and leaving. Celebrate any practice of no. Respect their pace.', '[{"id": "f0", "type": "textarea", "label": "A boundary I want to practice"}, {"id": "f1", "type": "textarea", "label": "Words I could use"}, {"id": "f2", "type": "textarea", "label": "How I will stand or sound"}, {"id": "f3", "type": "textarea", "label": "What I will do if it is not respected"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}]'::jsonb, array['sexual abuse', 'core DBT', 'boundaries']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('trusted-helpers-hand-drawing', 'Trusted Helpers Hand Drawing', 'kids'::resource_kind, 'A drawing of a child''s hand with a trusted helper on each finger.', 'Use it to help a child name the grown-ups they can tell if something feels wrong.', array['Children']::text[], '20 minutes', 'Trace the child''s hand and write a helper on each finger. Talk about telling a helper when something feels unsafe. A parent adds themselves. If a child discloses, follow your reporting duties and reassure the child they did the right thing in telling.', '[{"id": "f0", "type": "textarea", "label": "The helpers on my fingers"}, {"id": "f1", "type": "textarea", "label": "Who I would tell first"}, {"id": "f2", "type": "textarea", "label": "Words I can use to tell"}, {"id": "f3", "type": "textarea", "label": "What a helper does when I tell"}, {"id": "f4", "type": "textarea", "label": "Where I keep my hand drawing"}]'::jsonb, array['sexual abuse', 'kids', 'safety']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-time-and-place-grid', 'Coping Skills by Time and Place Grid', 'worksheet'::resource_kind, 'A grid matching coping skills to the places and times the client needs them.', 'Use it to help a client have a skill ready for each part of the day.', array['Adults', 'Teens']::text[], '25 minutes', 'List the client''s hardest times and places, such as the commute or a late evening. For each, choose a skill that fits that setting. Rehearse one. Review what was used and replace what was not.', '[{"id": "f0", "type": "textarea", "label": "Hard times or places in my day"}, {"id": "f1", "type": "textarea", "label": "A skill that fits each one"}, {"id": "f2", "type": "textarea", "label": "What I need to prepare"}, {"id": "f3", "type": "textarea", "label": "The skill I will start with"}, {"id": "f4", "type": "textarea", "label": "How I will remember it"}]'::jsonb, array['coping skills', 'planning', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('pocket-thought-cards-for-hard-moments', 'Pocket Thought Cards for Hard Moments', 'cbt'::resource_kind, 'A set of cards with balanced thoughts for the moments the client struggles most.', 'Use it to help a client have a helpful thought within reach in hard moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Write three or four balanced thoughts on cards in the client''s own words. Practice reading them in session. Keep them where the client will see them. Replace those that do not feel believable.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I face"}, {"id": "f1", "type": "textarea", "label": "A thought that is true and helpful"}, {"id": "f2", "type": "textarea", "label": "Another card to try"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my cards"}, {"id": "f4", "type": "textarea", "label": "How I will use one this week"}]'::jsonb, array['coping skills', 'core CBT', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('choice-point-coping-map', 'Choice Point Coping Map', 'act'::resource_kind, 'A map of the moment of choice between moving toward or away from what matters.', 'Use it to help a client notice a choice point and pick a move toward their values.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a choice point with moves toward and away. The client labels both with actual behaviors from their week. Practice noticing the choice point in the moment. Review which toward moves were possible.', '[{"id": "f0", "type": "textarea", "label": "The hard situation"}, {"id": "f1", "type": "textarea", "label": "Moves that take me away from what matters"}, {"id": "f2", "type": "textarea", "label": "Moves that take me toward it"}, {"id": "f3", "type": "textarea", "label": "What I notice at the choice point"}, {"id": "f4", "type": "textarea", "label": "My toward move for this week"}]'::jsonb, array['coping skills', 'core ACT', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('skill-swap-menu-by-intensity', 'Skill Swap Menu by Intensity', 'dbt'::resource_kind, 'A menu of skills sorted by how strong the emotion feels, with swaps for each.', 'Use it to help a client choose a skill that matches how intense they feel.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort skills into low, medium and high intensity. Have the client rate their emotions and pick from the right level. Swap ones that did not work. Practice a high intensity skill in session.', '[{"id": "f0", "type": "textarea", "label": "Low intensity skills"}, {"id": "f1", "type": "textarea", "label": "Medium intensity skills"}, {"id": "f2", "type": "textarea", "label": "High intensity skills"}, {"id": "f3", "type": "textarea", "label": "The skill I will practice"}, {"id": "f4", "type": "textarea", "label": "What I will swap in if it does not work"}]'::jsonb, array['coping skills', 'core DBT', 'skills']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-charades-circle', 'Coping Skills Charades Circle', 'game'::resource_kind, 'Players act out a coping skill while the group guesses it and shares when they might use it.', 'Use it to help a group learn each other''s coping skills through play.', array['Teens', 'Groups', 'Children']::text[], '25 minutes', 'Rules: draw a card, act out the skill without words, group guesses. The actor says when they might use it. Turns rotate. Debrief on skills people want to try. Keep it light and allow passing.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted out"}, {"id": "f1", "type": "textarea", "label": "How the group guessed it"}, {"id": "f2", "type": "textarea", "label": "When I might use it"}, {"id": "f3", "type": "textarea", "label": "A skill from someone else I will try"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('fear-picture-ladder-with-distance-steps', 'Fear Picture Ladder With Distance Steps', 'worksheet'::resource_kind, 'A ladder using pictures or distance to approach a feared thing gradually.', 'Use it to help a client approach a feared thing in small, planned steps.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder with at least eight rungs, using pictures, videos or distance. Predict distress for each. Choose the first rung. Stay on a rung until it feels manageable. Plan rewards for steps taken.', '[{"id": "f0", "type": "textarea", "label": "The thing I fear"}, {"id": "f1", "type": "textarea", "label": "Steps from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Predicted distress for each"}, {"id": "f3", "type": "textarea", "label": "The first rung and when I will do it"}, {"id": "f4", "type": "textarea", "label": "What I will do to cope during it"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('fear-forecast-and-reality-check-log', 'Fear Forecast and Reality Check Log', 'cbt'::resource_kind, 'A log comparing what the client expects in a feared situation with what happens.', 'Use it to help a client check fear predictions against real outcomes.', array['Adults', 'Teens']::text[], 'Two weeks', 'Predict outcome and distress before each exposure step, then record what happened. Review the gap. Keep entries brief. Note what helped.', '[{"id": "f0", "type": "textarea", "label": "The step I planned"}, {"id": "f1", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "Distress before and after"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'behavioral experiment', 'exposure']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('fear-along-for-the-ride-walk-sheet', 'Fear Along for the Ride Walk Sheet', 'act'::resource_kind, 'A sheet for taking a step toward something feared with fear coming along.', 'Use it to help a client take values-based steps toward a feared thing.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick a value that makes facing the fear worthwhile. Plan one step and decide how fear can come along. Practice noticing sensations. Review what the client did with fear as company.', '[{"id": "f0", "type": "textarea", "label": "The value behind facing my fear"}, {"id": "f1", "type": "textarea", "label": "The step I will take"}, {"id": "f2", "type": "textarea", "label": "What fear may say"}, {"id": "f3", "type": "textarea", "label": "How I will carry it along"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['phobias', 'core ACT', 'willingness']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('calming-plan-before-and-after-facing-a-fear', 'Calming Plan Before and After Facing a Fear', 'dbt'::resource_kind, 'A plan for steadying the body before and recovering after a step toward a fear.', 'Use it to help a client prepare and recover around each fear step.', array['Adults', 'Teens']::text[], '20 minutes', 'Plan a calm routine before and a recovery after: breathing, a warm drink, a short walk. Skills should support facing the fear, not avoid it. Review what recovery looked like.', '[{"id": "f0", "type": "textarea", "label": "What I will do to prepare"}, {"id": "f1", "type": "textarea", "label": "What I will do afterward"}, {"id": "f2", "type": "textarea", "label": "A person who knows my plan"}, {"id": "f3", "type": "textarea", "label": "How I will reward myself"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['phobias', 'core DBT', 'self-soothing']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('fear-detective-notebook-craft', 'Fear Detective Notebook Craft', 'kids'::resource_kind, 'A decorated notebook where a child investigates what a fear really does.', 'Use it to help a child get curious about a fear and gather facts.', array['Children']::text[], '30 minutes', 'Decorate a detective notebook. The child writes or draws clues about the fear, safe facts and brave steps. A parent helps with facts and cheers small steps without forcing. Reporting duties apply if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "The fear I am investigating"}, {"id": "f1", "type": "textarea", "label": "Clues I found"}, {"id": "f2", "type": "textarea", "label": "Safe facts I learned"}, {"id": "f3", "type": "textarea", "label": "A brave step I tried"}, {"id": "f4", "type": "textarea", "label": "Who my helper is"}]'::jsonb, array['phobias', 'kids', 'exposure']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-daily-appreciation-list', 'What My Body Does Daily Appreciation List', 'worksheet'::resource_kind, 'A list of what the body does for the client each day, beyond how it looks.', 'Use it to help a client appreciate what their body does for them.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with simple functions like carrying, hugging or breathing. Notice how it feels to look at the list. Add a few each week. Avoid any talk of appearance or measuring the body.', '[{"id": "f0", "type": "textarea", "label": "Things my body did today"}, {"id": "f1", "type": "textarea", "label": "Something I enjoyed doing"}, {"id": "f2", "type": "textarea", "label": "A function I take for granted"}, {"id": "f3", "type": "textarea", "label": "How I feel reading my list"}, {"id": "f4", "type": "textarea", "label": "One I will add"}]'::jsonb, array['body image', 'self-compassion', 'strengths']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('appearance-thought-sorting-sheet', 'Appearance Thought Sorting Sheet', 'cbt'::resource_kind, 'A sheet for catching thoughts about appearance and weighing more balanced ones.', 'Use it to help a client notice appearance thoughts and respond to them.', array['Adults', 'Teens']::text[], '25 minutes', 'Log moments when appearance thoughts rise, what triggered them, and what the client did. Draft a balanced thought. Avoid focusing on appearance details. Review patterns.', '[{"id": "f0", "type": "textarea", "label": "What set off the thought"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How strong the feeling was"}, {"id": "f3", "type": "textarea", "label": "A balanced response"}, {"id": "f4", "type": "textarea", "label": "What I did next"}]'::jsonb, array['body image', 'core CBT', 'thinking traps']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('valued-life-beyond-the-mirror-sheet', 'Valued Life Beyond the Mirror Sheet', 'act'::resource_kind, 'A sheet that links values to actions that have nothing to do with looks.', 'Use it to help a client spend more time on what matters than on appearance concerns.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would do with their time if appearance worries stepped aside. Plan one such act. Practice carrying the worry along. Review what the client noticed.', '[{"id": "f0", "type": "textarea", "label": "What I would do with my time"}, {"id": "f1", "type": "textarea", "label": "A value behind it"}, {"id": "f2", "type": "textarea", "label": "A worry that may come along"}, {"id": "f3", "type": "textarea", "label": "One act this week"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['body image', 'core ACT', 'values']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('kind-self-talk-practice-for-hard-days', 'Kind Self-Talk Practice for Hard Days', 'dbt'::resource_kind, 'A practice for offering oneself the words a caring friend would use on hard body days.', 'Use it to help a client shift from harsh to kind inner words.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what the client would say to a friend with the same worry. Write phrases and practice saying them. Pair with a soothing activity. Review which phrases felt believable.', '[{"id": "f0", "type": "textarea", "label": "What I say to myself on hard days"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "A kind phrase I can try"}, {"id": "f3", "type": "textarea", "label": "A soothing activity to pair"}, {"id": "f4", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['body image', 'core DBT', 'self-compassion']::text[], '2026-10-17T15:00:00+00:00'::timestamptz),
  ('partner-words-that-help-with-body-worries', 'Partner Words That Help With Body Worries', 'couples'::resource_kind, 'A conversation guide for partners to share what words help and what words hurt.', 'Use it to help a couple talk about body worries with care.', array['Couples']::text[], '30 minutes', 'Each partner shares words that help and words that do not. Practice supportive phrases. Avoid comments on appearance. Revisit as needed.', '[{"id": "f0", "type": "textarea", "label": "Words that help me"}, {"id": "f1", "type": "textarea", "label": "Words that hurt"}, {"id": "f2", "type": "textarea", "label": "What my partner can do instead"}, {"id": "f3", "type": "textarea", "label": "What I appreciate about my partner"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-10-17T15:00:00+00:00'::timestamptz)
