-- Clinician library: the 125 resources added on 2026-10-17 (five of every kind, five on every topic).
-- Generated with: python3 tools/therapist_resources_sql.py --since 2026-10-17
-- An upsert on slug, so applying it twice is harmless.

on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
